update content_bodies set title = '十和田市で穴場の観光スポットと美味しいグルメ７選', description = 'この動画は青森県への旅行を計画している方に向けて、十和田市の穴場グルメスポットを紹介しています。視聴者には、コメント欄で自分のおすすめをシェアすることが奨励されています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目指しています。運営メンバーは、旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見する手助けをしたいと考えています。動画では、蔦沼や十和田市現代美術館など、7つのおすすめスポットが紹介されており、各スポットの詳細はタイムスタンプで確認できます。' where id = 'hiv0aOZqc9lfmIlBYJFBo';
