update content_bodies set title = '7 Best Value Gourmet Foods to Try in Aichi', description = 'This video serves as a guide for those traveling to Aichi Prefecture, showcasing seven delicious and cost-effective gourmet options. Viewers are encouraged to share their own recommendations in the comments if they know of any other great places not mentioned in the video. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a variety of information related to sightseeing, transportation, accommodation, and dining. The team behind the channel believes that travel enriches life and helps individuals discover new possibilities. They invite viewers to explore and enjoy the journey.' where id = 'ROhAzKs0nJWAfjwAYjke_';
update content_bodies set title = '【妖怪と海鮮がすごい】鳥取旅行で欠かせない！境港のおすすめグルメ＆観光スポット7選', description = 'この動画では、鳥取県境港市の観光スポットを紹介しています。旅行や観光の参考にぜひご覧ください。動画に載っていないおすすめがあれば、コメント欄でシェアしてください。旅行の達人チャンネルは、観光、移動、宿泊、食事などの情報を提供し、旅行をより楽しくすることを目指しています。旅行を通じて人生を豊かにすることを願い、視聴者に新しい可能性を発見してもらうことを大切にしています。また、観光業に携わる方々には、地域の観光スポットや店舗のPRをお手伝いするサービスも提供しています。' where id = 'TgUYfk-PKZM5mHb5dXE94';
update content_bodies set title = 'Must-See Gourmet and Tourist Spots in Sakaiminato for Your Tottori Trip', description = 'This video provides recommendations for tourist spots in Sakaiminato City, Tottori Prefecture, perfect for your travel and sightseeing plans. If you have any additional recommendations not mentioned in the video, feel free to share them in the comments! The channel aims to enhance your travel experience by sharing various travel information, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities and experiences. For those in the tourism and travel industry, the channel offers assistance in promoting local attractions and businesses. Be sure to check out the official social media accounts for more updates!' where id = 'vlOU0CCUnFXC87JrY0zBS';
update content_bodies set title = '森の京都へようこそ～たくさんの「楽しい！」が待っている～', description = '京都駅からわずか20分の距離に位置する森の京都は、自然にあふれた場所です。ここには、たくさんの「楽しい！」が待っています。森の京都へようこそ。' where id = '0GZPnThZJEKsJc7y7BZLy';
update content_bodies set title = 'Welcome to the Forest of Kyoto - A Lot of Fun Awaits!', description = 'Just 20 minutes from Kyoto Station, the Forest of Kyoto is filled with nature and offers numerous enjoyable experiences. Welcome to the Forest of Kyoto, where many fun activities await you.' where id = '2e2L6J39QJUlVLa1oYal_';
update content_bodies set title = '森の京都へようこそ～たくさんの「楽しい！」が待っている～', description = '京都駅から20分の距離に位置する森の京都は、自然にあふれた場所です。ここにはたくさんの「楽しい！」が待っており、訪れる人々に素晴らしい体験を提供します。森の京都へようこそ！' where id = '0NgoBp37tpn_UvuyVQ_oJ';
update content_bodies set title = 'Welcome to the Forest of Kyoto - A Lot of Fun Awaits!', description = 'Just 20 minutes from Kyoto Station, the Forest of Kyoto is filled with nature and offers numerous enjoyable experiences. Welcome to the Forest of Kyoto!' where id = 'Nc1jHqSvsGVT-Wt94vu0b';
update content_bodies set title = 'こころ満たす旅へ、森の京都。', description = '自然と過ごす至福のひとときを体験し、森と川の恵みが溢れる心躍る体験が待っています。森の中で贅沢な時間を過ごし、自然と心を満たす旅に出かけましょう。森の京都地域振興社は、知られざる京都の魅力を世界に発信する公的旅行会社です。まだ誰も体験したことのない旅をご一緒しませんか。' where id = 'gRnIXZ2WvtjcH6kERy9tL';
update content_bodies set title = 'A Journey to Fulfill Your Heart in the Forest of Kyoto', description = 'Experience the bliss of spending time in nature, surrounded by the abundance of forests and rivers. A luxurious time in the woods awaits you, inviting you to embark on a journey that nourishes both nature and your spirit. Join us for an adventure unlike any other, as we unveil the hidden charms of Kyoto to the world through the Forest of Kyoto Regional Promotion Association, a public travel company. Discover experiences that no one has encountered before.' where id = '63luOO8npMUphgaNKkMqN';
update content_bodies set title = 'こころ満たす旅へ、森の京都。', description = '自然と過ごす至福のひとときを体験し、森と川の恵みが溢れる心躍る体験が待っています。森の中で贅沢な時間を過ごし、自然と心を満たす旅に出かけましょう。まだ誰も体験したことのない旅を共にし、知られざる京都の魅力を発信する公的旅行会社、森の京都地域振興社があなたをお待ちしています。' where id = 'IUDWmfO0erdRhds-NFW4g';
update content_bodies set title = 'A Journey to Fulfill Your Heart in the Forest of Kyoto', description = 'Experience the bliss of spending time in nature, surrounded by the abundance of forests and rivers. A luxurious time in the woods awaits you, inviting you to embark on a journey that nourishes both nature and your spirit. Join us for an adventure unlike any other, as we unveil the hidden charms of Kyoto to the world. Discover a travel experience that no one has encountered before.' where id = 'VjD5iWgcdQrcEipLX7HWW';
update content_bodies set title = '私は、森の京都ファン', description = '森の京都は、京都に位置する美しい地域で、太古からの自然と信仰を体現しています。伝統と地域文化に根ざした暮らしを示し、訪れる人々に季節の移ろいと日本の原風景を体験させます。この地域は、自然の美しさを通じて独自の癒しと魅力を提供しています。森の京都地域振興社は、京都の知られざる魅力を世界に発信する公的旅行会社であり、まだ誰も体験したことのない旅に人々を招待しています。' where id = 'nJJpnbVepZG347PNEE6B5';
update content_bodies set title = 'I Am a Fan of the Forest of Kyoto', description = 'The Forest of Kyoto is a beautiful area in Kyoto that embodies ancient nature and spirituality. It showcases a lifestyle deeply rooted in tradition and local culture, allowing visitors to experience the changing seasons and the essence of Japan''s original landscapes. The region offers a unique healing experience and charm through its natural beauty. The Mori no Kyoto Regional Promotion Association is a public travel company dedicated to sharing the hidden attractions of Kyoto with the world, inviting travelers to embark on journeys that have yet to be experienced.' where id = 'fnYSg9X1Z005aNnUsFqfj';
update content_bodies set title = '森の京都での活動', description = '森の京都は、緑豊かな里山の環境で、清らかな水が流れ、長い間受け継がれてきた知恵と技が息づく体験を提供しています。自然と人々が交わる調和の取れた暮らしに参加し、森の美しさを祝うさまざまな活動を楽しむことができます。森の京都地域振興社は、京都の知られざる魅力を世界に発信する公的旅行会社であり、まだ誰も体験したことのないユニークな旅に皆さんを招待しています。' where id = '_-sfVJ_LT75zsCkkBh2WX';
update content_bodies set title = 'Activity in Woodland Kyoto', description = 'Woodland Kyoto offers a rich experience in a lush satoyama environment, where clear waters flow and the wisdom and skills passed down through generations thrive. Visitors are invited to join in the harmonious lifestyle that intertwines nature and people, engaging in various activities that celebrate the beauty of the forest. The Mori no Kyoto Regional Promotion Association, a public travel company, aims to share the hidden charms of Kyoto with the world, inviting everyone to embark on unique journeys that have yet to be experienced.' where id = '-acVV5zPlX0yu557YVBuT';
update content_bodies set title = '和知人形浄瑠璃～地域無形文化遺産 森育ちの文化が待っている～', description = '「森の京都」として知られる京丹波町は、豊かな森と共に発展してきました。この動画では、森と人が育んできた伝統文化の魅力を紹介します。和知人形浄瑠璃は約150年前に農家の閑散期に始まり、通常3人で操る人形を1人で扱う独特のスタイルが特徴です。太夫、三味線、人形の三業が一体となったこの芸は、地域の誇る伝統技術です。和知伝統芸能常設館で定期公演が行われています。この動画は、文化庁の地域無形文化遺産継承支援事業の一環として制作されました。' where id = 'c6AcMTJKWKlOdlltOUTMK';
update content_bodies set title = 'Wachi Puppet Joruri - Intangible Cultural Heritage of Kyotanba Town', description = 'Kyotanba Town, known as ''Forest Kyoto,'' has developed alongside its rich forests, benefiting from the blessings of the mountains. This video showcases the captivating traditional culture nurtured by the relationship between the forest and the people in six towns of the Forest Kyoto area. Wachi Puppet Joruri has its roots about 150 years ago, originating from farmers enjoying puppet performances during their off-season. A unique feature of this art is that one person operates the puppets, which are typically handled by three. The performance combines the roles of the tayu (narrator), shamisen player, and puppeteer, showcasing a traditional skill that the community takes pride in. Regular performances can be seen at the Wachi Traditional Performing Arts Permanent Hall. This video was produced as part of a project by the Agency for Cultural Affairs to support the preservation of intangible cultural heritage.' where id = 'h-ClRC4XUBUhw_Vu9dL9g';
update content_bodies set title = '森の京都・伝統を紡ぐ人々の物語', description = '森の京都エリアには、日本刀の刀鍛冶や友禅和紙など、京の文化を支えてきた伝統工芸が今も残っています。この動画では、技術者たちが伝統を受け継ぎ未来へつなぐ姿、そして彼らの思いを描いています。この土地の宝として、そして生活の一部として、次の世代へと紡がれる伝統工芸やその技術をご覧ください。' where id = 'u9892cxLDgccOKZcU1Kuq';
update content_bodies set title = 'Stories of People Weaving Tradition in the Forest of Kyoto', description = 'The Forest of Kyoto area is home to traditional crafts that have supported Kyoto''s culture, such as Japanese swordsmithing and Yuzen washi paper. This video depicts the artisans who inherit these traditions and connect them to the future, showcasing their dedication. Viewers can witness these traditional crafts and techniques, treasured as part of the local heritage and daily life, being passed down to the next generation.' where id = 'hOCoSauwhs_3jt5TDokrs';
update content_bodies set title = '実はすぐそこ！京都駅から森の京都まで【アクセス紹介動画】', description = '京都市内から自然に触れたいと思っている方の中には、遠く感じる方も多いかもしれません。しかし、実際には電車で一本、京都駅から亀岡まで20分で行けます。乗り換えもなく、車窓からは美しい田園風景を楽しむことができ、自然の雄大さを感じながら森の京都へ訪れることができます。ぜひ足を運んでみてください。' where id = 'bMCrIFKmKolPMKFs57SkQ';
update content_bodies set title = 'Access Guide from Kyoto Station to Mori no Kyoto', description = 'Many people may think that experiencing nature requires traveling far from Kyoto city. However, it is actually very accessible by train. You can reach Kameoka, the gateway to Mori no Kyoto, in just 20 minutes without any transfers from Kyoto Station. Enjoy the beautiful rural scenery from the train window and feel the grandeur of nature as you make your way to Mori no Kyoto!' where id = 'vFgOqaWyAxY1rQJhOe1MI';
update content_bodies set title = '森の京都【秋冬】', description = '「森の京都」は、嵐山周辺の知られざる魅力を探求する旅へと誘います。嵐山を流れる水の源や、金閣寺の借景となる森の広がりについての疑問を提起します。この地域は、清らかな山の水と肥沃な大地が人々の暮らしや地域文化を支えてきた場所です。素朴な里山の風景の中で、厳かな森や河と共存しながら生きる人々がいます。秋冬の彩り豊かな景色と、自然と共に暮らす人々の美しさを楽しむことができます。この旅は、歴史と伝統の京都から、自然と生命が息づく「森の京都」へとつながります。' where id = '14Q99UK1pxTD0ZSW5GTSV';
update content_bodies set title = 'Woodland Kyoto -Deep into the heart of authentic Japan-', description = 'Woodland Kyoto invites you to explore the lesser-known aspects of Kyoto, particularly the area around Arashiyama. It raises questions about the origins of the water flowing through Arashiyama and the extent of the forest that serves as a backdrop for the Golden Pavilion. This region, known as ''Woodland Kyoto,'' is characterized by pure mountain springs and fertile land that have supported local culture and livelihoods. Amidst the rustic landscapes, people coexist with the majestic forests and rivers, utilizing inherited wisdom. Visitors can enjoy the vibrant autumn and winter scenery, as well as the beauty of those living in harmony with nature. This journey connects the historical and traditional aspects of Kyoto with the life-giving essence of ''Woodland Kyoto.''' where id = 'SjXXzRIR8xHMfhYuyls7F';
update content_bodies set title = 'さっぽろテレビ塔 4K／北海道の絶景景色', description = 'BEST HOKKAIDOでは、北海道の魅力的な観光スポットや資源を紹介しています。今回は、さっぽろテレビ塔からの絶景をお届けします。札幌の夜景は「日本新三大夜景」に認定されており、さっぽろテレビ塔は1957年に完成し、大通公園にそびえ立つランドマークです。地上約90mの展望台からは、季節ごとに変わる公園の美しい景色やイベントを楽しむことができます。冬にはホワイトイルミネーションや雪まつりが開催され、特等席となります。2022年3月19日から27日には「PLANET FLOWERS SAPPORO」というイベントが開催され、植物と光の幻想的な空間が楽しめます。また、3月15日から29日まで、ハッシュタグ「#札幌夜景フォト」を付けて夜景写真をSNSに投稿するキャンペーンも行われ、素敵な景品が当たるチャンスがあります。' where id = 'KQsgvDwPbstWkS_djvAKJ';
update content_bodies set title = 'Sapporo TV Tower 4K / Superb view of Hokkaido', description = 'BEST HOKKAIDO introduces the attractive tourist spots and resources of Hokkaido. This feature showcases the stunning views of Hokkaido from various angles. Sapporo''s night view has been recognized as one of the ''New Three Major Night Views of Japan.'' The Sapporo TV Tower, completed in 1957, stands as a landmark in Odori Park, which divides the city into north and south. From its observatory, approximately 90 meters above ground, visitors can enjoy the park''s beautiful scenery and seasonal events. In winter, it offers a prime view of the White Illumination and the Snow Festival. An event called ''PLANET FLOWERS SAPPORO'' will take place from March 19 to 27, 2022, featuring a magical display of plants and lights. Additionally, a photo campaign on social media encourages sharing night view images with the hashtag ''#Sapporo Night View Photo'' for a chance to win prizes.' where id = 'XDH7vpaYBl6uUkQRXjAF_';
update content_bodies set title = 'こさぶろうが行く！城街コレクション②～宇和島城編～', description = '江戸時代以前から残る現存12天守を特集します。お城の魅力はもちろん、城下町としての魅力も、キューティーブロンズのこさぶろうさんが伝えます。' where id = 'CfrjxA_I848DERHlvu7_i';
update content_bodies set title = 'Kosaburo Goes! Castle Town Collection ② - Uwajima Castle Edition', description = 'This episode features the existing 12 castles with their keep structures that have survived since before the Edo period. Kosaburo from Cutie Bronze conveys the charm of the castle itself as well as the appeal of the castle town.' where id = 'fxvfuoq6-EfV8Rjvkwb3i';
update content_bodies set title = 'こさぶろうが行く！城街コレクション⑦～松江城編～', description = '江戸時代以前から残る現存12天守を紹介します。お城の魅力はもちろんですが、キューティーブロンズのこさぶろうさんが城下町としての魅力も伝えます。' where id = '2VxgKuHAYy9_T8U7LIshE';
update content_bodies set title = 'Kosaburo Goes! Castle Town Collection No. 7 - Matsue Castle Edition', description = 'This edition highlights the existing 12 castle towers that have survived since before the Edo period. The charm of the castle itself is certainly captivating, but Kosaburo from Cutie Bronze also conveys the appeal of the castle town.' where id = 'CsvszJDY22UDn9gZvQJHM';
update content_bodies set title = '【舞鶴×SUNTORY】スパイス薫る”海軍ホットウヰスキー”もお好きでしょ', description = '寒い夜にぴったりの「海軍ホットウヰスキー・カクテル」をご紹介します。スパイスが香るこの飲み物は、海軍に由来するレシピを基にしており、体を温めてくれます。「海軍レトロブレンド」は、大正7年に発行された海軍の料理教科書に記載された「ホットウヰスキー」の復刻版です。ナツメグやアンゴスチュラビター、角砂糖、クローブ、レモン、ブランデーまたはウイスキーを使ったレシピが特徴です。また、現代風にアレンジされた「ホットカルダモンビーム」や「翠ホット」もあり、スパイスの変化を楽しむことができます。おうちでもお店でも、ぜひお試しください。' where id = 'J3_lm6PffKe8Ud6-Q_sNg';
update content_bodies set title = 'Maizuru x SUNTORY: Spiced ''Navy Hot Whisky'' You’ll Love', description = 'How about a ''Navy Hot Whisky Cocktail'' on a cold night? This spiced drink warms you up and is based on a recipe with naval ties. The ''Navy Retro Blend'' is a revival of the ''Hot Whisky'' from the Navy''s cooking textbook published in 1918. Experience the retro flavor of the Showa era. The recipe includes ingredients like nutmeg, Angostura bitters, sugar, cloves, lemon, and brandy or whisky. There are also modern variations like ''Hot Cardamom Beam'' and ''Midori Hot,'' which incorporate spices for a unique taste experience. Enjoy these drinks at home or in bars, and celebrate the 120th anniversary of the Maizuru Naval Base.' where id = 'DpgnC7KbYPS3LiaMukbRW';
update content_bodies set title = '鹿児島県指宿市/俣川洲（またごし）〈ドローン４K撮影〉', description = '俣川洲は山川港の南部に位置し、海と火山によって形成された岩です。観光地化されておらず、地元の人々や自然愛好家に知られる穴場スポットです。南西方向には開聞岳、手前には竹山が見え、角度によっては三つを同時に楽しむことができます。陸地からは伏目海岸方面から見ることができますが、トンネル方向の絶景を狙うには角度が重要です。海蝕によって自然にできたトンネル「海食洞」は、小舟が通れるほどの大きさです。できるだけ海上からの観察をおすすめします。' where id = '8H7e_NmLMT5N0gJm8bKa8';
update content_bodies set title = 'Matagoshima, Ibusuki City, Kagoshima Prefecture / Drone 4K Shooting', description = 'Matagoshima is a hidden gem located south of Yamakawa Port, formed by the sea and volcanic activity. It is not a tourist spot, known mainly to locals and nature enthusiasts. To the southwest, you can see Mount Kaimondake, and in the foreground, Takeyama. Depending on the angle, all three can be enjoyed simultaneously. While it can be viewed from the land near Fushime Coast, capturing the stunning scenery from the tunnel direction requires careful angling. The natural tunnel, known as ''Kaishokudo,'' is large enough for small boats to pass through. Observing from the sea is highly recommended.' where id = 'beXhdmH7GYSwEZga2YNsd';
update content_bodies set title = '鹿児島県指宿市/知林ヶ島（ドローン４K撮影）', description = '知林ヶ島は鹿児島県指宿市に位置する周囲約3kmの無人島で、錦江湾の透明度の高い海に囲まれた自然豊かな景観が魅力です。干潮時には砂州が現れ、大潮の際にはその時間が長く続くため、歩いて島に渡ることができます。この砂州は3月から10月の干潮時にのみ現れ、干潮の時間は日によって異なるため、訪れる際には潮見表の確認が推奨されます。ぜひ知林ヶ島を訪れて、その美しい景色を体験してみてください。' where id = 'GynD99BuVzA6lqPwo4Vbt';
update content_bodies set title = 'Chiringashima Island in Ibusuki City, Kagoshima Prefecture (4K Drone Footage)', description = 'Chiringashima is an uninhabited island located in Ibusuki City, Kagoshima Prefecture, surrounded by the clear waters of Kinko Bay and measuring approximately 3 km in circumference. The island is known for its rich natural scenery. During low tide, a sandbar appears, allowing visitors to walk to the island, especially during spring tides when this phenomenon lasts longer. The sandbar is visible only from March to October during low tide, and the timing varies daily, so checking the tide schedule is recommended before visiting. Be sure to experience Chiringashima firsthand.' where id = 'AbCXXfIey7WipdwYli--h';
update content_bodies set title = '【鹿児島県指宿市】あなたがすきです、指宿15', description = '指宿を旅したくなるような、あたたかい時間を提供しています。皆さんが再びお越しいただける日を心待ちにしています。' where id = 'OfefzSi1eqk8L1xtYpTS7';
update content_bodies set title = 'Ibusuki, Kagoshima Prefecture: I Love You, Ibusuki 15', description = 'A warm experience that makes you want to travel to Ibusuki. We look forward to the day when everyone can visit again.' where id = 'VjqVyk4T3qc83RAo4QbpA';
update content_bodies set title = '福岡県うきは市の一の瀬焼', description = 'この動画では、福岡県うきは市の一の瀬焼を紹介しています。一の瀬焼は、豊臣秀吉が朝鮮徴兵の際に陶工を招いたことが起源とされています。1840年頃には最盛期を迎え、有馬藩の御用窯となりましたが、その後廃窯となりました。しかし、郷土の窯を再び復活させたいという熱意によって発展し、現在では5つの窯元が存在しています。' where id = 'C1GrCb1HQBllpHGDkMHJT';
update content_bodies set title = 'Ichinoseyaki in Ukiha City, Fukuoka Prefecture', description = 'This video introduces Ichinoseyaki, a type of pottery from Ukiha City in Fukuoka Prefecture. Ichinoseyaki is said to have originated when Toyotomi Hideyoshi invited potters during the Korean draft. It reached its peak around 1840 and became the official kiln of the Arima clan. Although it was abandoned later, the passion for reviving the local kiln led to its development, and currently, there are five active kilns.' where id = 'cvBGBANwnxz5qbgm3Zxm7';
update content_bodies set title = '【うきはの職人】行徳製菓＃1', description = 'うきはの職人を紹介します。吉井町の行徳せんべいを作る行徳さんは、もうすぐ90歳です。彼が作るお菓子の素朴で温かみのある味は、彼自身の手によるものかもしれません。' where id = 'QrS9aoPcswsgrilasZK0G';
update content_bodies set title = 'Craftsman of Ukiha: Gyotoku Confectionery #1', description = 'Introducing the craftsman of Ukiha! Gyotoku Senbei from Yoshii Town, Mr. Gyotoku, is nearly 90 years old. The simple and warm taste of his sweets may be attributed to his craftsmanship.' where id = '0PP61Gf6j9mGk88WRn_2D';
update content_bodies set title = '福岡県うきは市の一の瀬焼き', description = 'この動画では、福岡県うきは市の伝統的な陶器である一の瀬焼きについて紹介しています。一の瀬焼きの起源は、豊臣秀吉が朝鮮徴兵の際に陶工を招いたことに遡ります。1840年頃に最盛期を迎え、有馬藩の御用窯となりましたが、後に廃窯となりました。しかし、地元の窯を再興しようという熱意によって、現在は5つの窯元が存在し、活発に活動しています。2023年5月3日から7日まで春の陶器まつりが開催され、5軒の窯元が集まり、見学や販売が行われます。' where id = 'UWI1lJeRYA3H4K1gUnuVf';
update content_bodies set title = 'Ichinose-yaki in Ukiha City, Fukuoka Prefecture', description = 'This video introduces Ichinose-yaki, a traditional pottery from Ukiha City in Fukuoka Prefecture. The origins of Ichinose-yaki trace back to Toyotomi Hideyoshi, who invited potters during the Korean draft. It reached its peak around 1840 and became the official kiln of the Arima clan, but eventually fell into disuse. However, due to a strong desire to revive the local kiln, it has developed into a thriving craft with five active kilns today. A spring pottery festival will be held from May 3 to May 7, 2023, featuring all five kilns, offering tours and sales.' where id = 'UKY6NqZXWLHaT5-DYnMaX';
update content_bodies set title = '【福岡県うきは市】道の駅うきはからパールワイン登場！', description = '令和5年3月25日、道の駅うきはで新たにぶどうのパールワインが発売されました。このワインは、うきは市で収穫されたものの、傷などで出荷できないぶどうを使用して作られています。同日、プロジェクトメンバーによる試飲会が行われ、果実の澱が含まれた香り豊かで美味しいワインが出来上がりました。今後は様々なフルーツを使った商品化が期待されており、うきはの実りが皆さんに届くことを願っています。' where id = 'VYyNbch1SFQAM-NNaEtXQ';
update content_bodies set title = 'New Pearl Wine from Ukiha City, Fukuoka Prefecture!', description = 'On March 25, 2023, a new pearl wine made from grapes was launched at the Ukiha Road Station. The wine is crafted from grapes that could not be shipped due to imperfections. On the same day, a tasting event was held with project members, who found the wine to be aromatic and delicious, with fruit sediment present. There is high anticipation for future products made from various fruits, ensuring that the bounty of Ukiha is fully enjoyed by everyone.' where id = 'QtGMa_Mu5y-Oot5hNxv7Z';
update content_bodies set title = '【うきはの今 】春バージョン', description = 'この動画は、うきは市地域おこし協力隊の井上宗之輔によって制作され、春のうきはの美しさを紹介しています。浮羽稲荷神社や調音の滝、つづら棚田など、福岡県の観光名所が取り上げられています。動画は、うきはの観光促進を目的としており、地域の自然景観や文化的なスポットの美しい映像が特徴です。' where id = 'W3GMUQY_V1lED0Jf182oB';
update content_bodies set title = 'Ukiha Now: Spring Version', description = 'This video, produced by Munenobu Inoue, a community revitalization cooperation team member in Ukiha City, showcases the beauty of Ukiha during spring. It highlights various attractions in the region, including the Ukiha Inari Shrine, Chouon Falls, and the Tsuzura Rice Terraces, all located in Fukuoka Prefecture, Kyushu. The video aims to promote tourism in Ukiha and features stunning visuals of the area''s natural landscapes and cultural sites.' where id = 'SeB1mcyNekt9FozoesEBv';
update content_bodies set title = '【2025年】雫石よしゃれ祭【新生雫石町70周年記念】', description = '雫石よしゃれ祭は、毎年8月11日に開催される雫石町の夏の一大イベントです。メイン会場はよしゃれ通り商店街で、神輿運行やよしゃれ踊り、さんさ踊りなど、各団体による多彩なパレードが行われ、最後はさんさとよしゃれの輪踊りで締めくくられます。メイン会場の他にも、よさこい演舞や雫石郷土芸能競演、南部よしゃれ全国大会最優秀賞者競演なども開催されます。8月11日は「よしゃれの里 雫石町」へぜひお越しください！' where id = 'OEqLSgglEbki7McND67uk';
update content_bodies set title = 'Shizukuishi Yosharai Festival 2025: Celebrating 70 Years of Shizukuishi Town', description = 'The Yosharai Festival is a major summer event held annually on August 11 in Shizukuishi Town. The main venue is the Yosharai shopping street, where various groups showcase colorful parades featuring mikoshi (portable shrines), Yosharai dances, and Sansa dances. The festival concludes with a circle dance of Sansa and Yosharai. In addition to the main events, there are performances of Yosakoi dance, local folk arts competitions, and showcases of the best performers from the National Sansa Yosharai Competition. Visitors are encouraged to come to ''Yosharai no Sato Shizukuishi Town'' on August 11!' where id = 'UNBnGrgr1YehSsAwHhxK9';
update content_bodies set title = '御所ダム探検隊がゆく！【ダムカレーと光のトンネル】', description = '夏休みの思い出づくりに、涼しい御所ダムの監査廊内イルミネーション見学に出かけましょう！ダムカレーを味わい、光のトンネルをくぐりながら、夏の御所湖の美しい景色を家族や友人と楽しむことができます。監査廊の最深部は撮影企画用に特別に案内され、通常の見学コースには含まれない船の乗船も特別に行われました。詳細は、一般社団法人しずくいし観光協会のホームページをご覧ください。' where id = 'mzODP4Bj2hqvVa0hhxWvw';
update content_bodies set title = 'Exploring Goshodam! [Dam Curry and the Tunnel of Light]', description = 'Join us for a cool summer outing to see the illuminated inspection corridor of Goshodam, creating wonderful summer memories! Enjoy dam curry, walk through the tunnel of light, and take in the beautiful scenery of Goshoko with your family and friends. Special access to the deepest part of the inspection corridor was arranged for a photography project, and boat rides were provided, which are not included in the regular tour. For more information, visit the Shizukuishi Tourism Association''s website.' where id = 'vqy8xoWxigxGig83IzXo1';
update content_bodies set title = 'こさぶろうが行く！城街コレクション⑧～姫路城編～', description = '江戸時代以前から残る現存12天守を特集します。お城の魅力はもちろん、城下町としての魅力も、キューティーブロンズのこさぶろうさんが伝えます。' where id = 'wBYb-m4xczY-VMF2B0e0C';
update content_bodies set title = 'Kosaburo Goes! Castle Town Collection Vol. 8 - Himeji Castle Edition', description = 'This episode features the existing 12 tenshu (castle towers) that have remained since before the Edo period. Kosaburo from Cutie Bronze conveys the charm of the castle itself as well as the appeal of the castle town.' where id = 'LxUo-koe0ZtpiprhizdHr';
update content_bodies set title = 'こさぶろうが行く！城街コレクション⑨～犬山城編～', description = '江戸時代以前から残る現存12天守を特集しています。お城の魅力はもちろん、城下町としての魅力も、キューティーブロンズのこさぶろうさんが伝えます。' where id = 'cr3Y8QBJK-pdAWphwW3nH';
update content_bodies set title = 'Kosaburo Goes! Castle Town Collection No. 9 - Inuyama Castle Edition', description = 'This edition features the existing 12 tenshu that have remained since before the Edo period. Kosaburo from Cutie Bronze conveys the charm of the castle as well as the appeal of the castle town.' where id = 'oNVUXRaq0H6fwCLrTzehd';
update content_bodies set title = '雫石町の桜', description = '雫石町は、春になると美しい桜が咲き誇ることで知られています。絶景を楽しむことができるこの地域は、桜の花の下での散歩に最適で、地元の人々や観光客に人気のスポットとなっています。雫石町の桜は、岩手県の自然の魅力を引き立てる季節のハイライトです。' where id = 'OzLEQp6hoOCIHtvnQRqt6';
update content_bodies set title = 'Cherry Blossoms in Shizukuishi Town', description = 'Shizukuishi Town is renowned for its stunning cherry blossoms, offering breathtaking views that attract visitors each spring. The area is perfect for leisurely walks among the blooming sakura, making it a popular destination for both locals and tourists. The beauty of the cherry blossoms in Shizukuishi is a highlight of the season, showcasing the natural charm of Iwate Prefecture.' where id = 'ob5Hd7KETHzg7JjLQdDuO';
update content_bodies set title = 'ゆこたんの森', description = 'ゆこたんの森は、岩手県雫石町長山猫沢に位置し、郵便番号は020-0585です。お問い合わせは、電話019-693-3600またはファックス019-693-3535で受け付けています。この施設は宿泊と温泉を提供しており、美しい岩手地域でのリラクゼーションに最適な目的地です。' where id = 'CuAxyqh2wl6Zra1MIJ2tG';
update content_bodies set title = 'Yukotan''s Forest', description = 'Yukotan''s Forest is located in Nagayama Nekozawa, Shizukuishi Town, Iwate Prefecture, with the postal code 020-0585. For inquiries, you can contact them at TEL 019-693-3600 or FAX 019-693-3535. The facility offers accommodations and hot springs, making it a perfect destination for relaxation in the beautiful Iwate region.' where id = 'V-zxKB74fvxuys6u-bWUA';
update content_bodies set title = '鶯宿温泉　川長', description = '鶯宿温泉　川長は、岩手県岩手郡雫石町鶯宿10-31-23に位置しています。郵便番号は020-0574です。お問い合わせは019-695-2171まで、ファックスは019-695-2624に送信できます。この宿は温泉で知られており、自然豊かな岩手地域にあります。' where id = 'PhyOH3rAftsVTH8K1isPk';
update content_bodies set title = 'Uguisu-yu Onsen Kawacho', description = 'Uguisu-yu Onsen Kawacho is located at 10-31-23 Uguisu-yu, Shizukuishi Town, Iwate Prefecture, 020-0574, Japan. For inquiries, you can contact them at 019-695-2171 or send a fax to 019-695-2624. The establishment is known for its hot springs and is situated in the scenic Iwate region.' where id = '_R16BFSAMLv4IOmC-X0ue';
update content_bodies set title = '小岩井農場', description = '小岩井農場は、岩手県岩手郡雫石町丸谷地36-1に位置しています。お問い合わせは019-692-4321まで、受付時間は9:00から17:00です。小岩井農場は、岩手の観光名所として知られています。' where id = '1xQ-TXIxrw_ohmyMpSjIB';
update content_bodies set title = 'Koiwai Farm', description = 'Koiwai Farm is located at 36-1 Maruyachi, Shizukuishi Town, Iwate County, Iwate Prefecture, 020-0507, Japan. For inquiries, please call 019-692-4321 during the hours of 9:00 AM to 5:00 PM. Koiwai Farm is a popular tourist destination in Iwate.' where id = 'iUhbyE7WP3x1ZyCUsDxpn';
update content_bodies set title = '国立公園で朝活！「天空の丘」と「あみはりの森」お散歩会🍃＠休暇村岩手網張温泉', description = '休暇村岩手網張温泉で開催される「天空の丘」と「あみはりの森」のお散歩会に参加しませんか？早朝に「天空のリフト」で「天空の丘」へ向かい、パノラマや雲海を楽しむことができます。その後、スタッフが「天空の丘」から「あみはりの森」へ案内し、ここでしか見られない美しい風景を堪能できます。' where id = 'tBm1uiHr6SjQa4LfBY1J9';
update content_bodies set title = 'Morning Activities in National Parks! Walking Event at ''Sky Hill'' and ''Amihari Forest'' 🍃 @ Qkamura Iwate Amihari Onsen', description = 'Join the walking event at ''Sky Hill'' and ''Amihari Forest'' starting with an early morning ride on the ''Sky Lift'' to ''Sky Hill''. Enjoy panoramic views and sea of clouds. Staff will guide you from ''Sky Hill'' to ''Amihari Forest'', showcasing unique landscapes that can only be seen here.' where id = 'eOmEz3keeDMiKJ8bRs87a';
update content_bodies set title = 'ペンション 山賊', description = 'ペンション 山賊は、岩手県岩手郡雫石町の長山に位置しています。住所は、岩手山22-194、郵便番号は020-0585です。お問い合わせは019-693-4044までどうぞ。このペンションは、美しい岩手地域での快適な宿泊体験を提供しています。' where id = 'MJ8bvVgUfUsOFCVki7Nbl';
update content_bodies set title = 'Pension Sanzoku', description = 'Pension Sanzoku is located in Nagayama, Iwate, Japan. The address is 22-194 Iwatezan, Shizukuishi Town, Iwate District, 020-0585. For inquiries, you can contact them at 019-693-4044. This pension offers a cozy accommodation experience in the beautiful Iwate region.' where id = 'mUJxCyuZHv3FlTrmqffDf';
update content_bodies set title = '民宿 なかがわ', description = '民宿 なかがわは、岩手県岩手郡雫石町長山に位置する宿泊施設です。住所は、〒020-0585 岩手県岩手郡雫石町長山篠ヶ川原174です。お問い合わせは、電話019-693-2422、ファックス019-693-2436で受け付けています。詳細は公式ウェブサイト（http://minshuku-nakagawa.com/）をご覧ください。伝統的な日本の宿泊体験を提供し、静かな環境での滞在を楽しむことができます。' where id = 'vF7ZUU8wCeF3vOVoMzoY8';
update content_bodies set title = 'Minpaku Nakagawa', description = 'Minpaku Nakagawa is a guesthouse located in Nagayama, Shizukuishi Town, Iwate Prefecture, Japan. The address is 174 Shino-gawara, Shizukuishi, Iwate-gun, 020-0585. For inquiries, you can contact them at TEL: 019-693-2422 or FAX: 019-693-2436. More information can be found on their website: http://minshuku-nakagawa.com/. The guesthouse offers a traditional Japanese lodging experience in a serene environment.' where id = '6-qy_fgT3ea4K6UnWUgrt';
update content_bodies set title = '民宿 坂井荘', description = '民宿 坂井荘は、岩手県岩手郡雫石町長山早坂に位置する宿泊施設です。住所は、〒020-0585 岩手県岩手郡雫石町長山早坂27です。お問い合わせは、電話019-693-2945、ファックス019-693-2225で受け付けています。' where id = 'CerhHoQ3XLP3efX3bSsxi';
update content_bodies set title = 'Minpaku Sakaisou', description = 'Minpaku Sakaisou is a guesthouse located in Nagayama Hayasaka, Shizukuishi Town, Iwate Prefecture, Japan. The address is 27 Nagayama Hayasaka, Shizukuishi, Iwate, 020-0585. For inquiries, you can contact them at TEL: 019-693-2945 or FAX: 019-693-2225.' where id = 'kVcEtefNkHjBncLtrlC-x';
update content_bodies set title = '小枝旅館', description = '小枝旅館は、岩手県雫石町に位置する民宿です。住所は〒020-0574 雫石町鴬宿6-24-4です。お問い合わせは、電話019-695-2126、ファックス019-695-2181で受け付けています。温泉が楽しめるアットホームな雰囲気の宿です。' where id = 'xPphdfDzRQqv7w4E2dFVM';
update content_bodies set title = 'Koe Inn', description = 'Koe Inn is a guesthouse located in Shizukuishi Town, Iwate Prefecture. The address is 6-24-4 Ushuku, Shizukuishi, 020-0574. For inquiries, you can contact them at TEL: 019-695-2126 or FAX: 019-695-2181. The inn offers a cozy atmosphere and is known for its hot springs.' where id = 'yT7Fl-whZpQWapVaqCrBX';
update content_bodies set title = 'ヴィラ館々倶楽部', description = 'ヴィラ館々倶楽部は、岩手県岩手郡雫石町に位置する宿泊施設です。この施設はペンションスタイルの宿泊体験を提供しています。詳細については、公式ウェブサイト（http://www.kankanclub.co.jp/）を訪れるか、電話（019-693-3339）またはファックス（019-693-3340）でお問い合わせください。' where id = 'rd6w7ZP7IgtQHRdzgLmUV';
update content_bodies set title = 'Villa Kankan Club', description = 'Villa Kankan Club is a lodging facility located in Shizukuishi Town, Iwate Prefecture, Japan. The club offers a pension-style accommodation experience. For more information, you can visit their website at http://www.kankanclub.co.jp/ or contact them via phone at 019-693-3339 or fax at 019-693-3340.' where id = '-KYolCNJDhPtBmAaRQ4Oa';
update content_bodies set title = '南信州まつかわ「朝摘みの”さくらんぼ”を農家よりお届けします」', description = '今年も南信州まつかわのさくらんぼは順調に育っています。6月中旬からさくらんぼ狩りを開始する予定ですが、国内外の状況を考慮し、今シーズンのお受入れを決定します。この時期、自宅で過ごす方も多いと思いますので、私たちのさくらんぼを楽しんでいただけるように「朝摘みさくらんぼを農家よりお届けします」という企画を立てました。ぜひご自宅で南信州まつかわのさくらんぼをお召し上がりください。皆様のご購入がさくらんぼ農家の笑顔につながることを願っています。' where id = 'ivGUzNoplnXZuunNg8dIm';
update content_bodies set title = 'Freshly Picked Cherries from Matsukawa, Minami-Shinshu Delivered from Farmers', description = 'This year, cherries from Matsukawa, Minami-Shinshu are growing well. Cherry picking is scheduled to start around mid-June, but we will decide on the season''s acceptance based on domestic and international conditions. Many people may be spending time at home during this period. Therefore, we have planned a project to deliver ''freshly picked cherries from farmers'' to allow you to enjoy our cherries at home. Please enjoy Matsukawa''s cherries at home. We hope your purchases will bring smiles to cherry farmers.' where id = 'Vx3Pdg2SLLUzO9dM3fmOI';
update content_bodies set title = '益田市の人気観光スポットと美味しいグルメ７選', description = 'この動画は、島根県への旅行を考えている方に向けて、益田市のおすすめ観光スポットを紹介しています。動画で紹介されていないおすすめがあれば、ぜひコメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目的としています。運営メンバーは、旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見することを促しています。公式SNSアカウントをフォローし、チャンネル登録をお忘れなく。' where id = 'GSi4EGx9viY9oI4Aau2my';
update content_bodies set title = 'Popular Tourist Spots and Delicious Gourmet in Masuda City, Shimane', description = 'This video serves as a guide for those traveling to Shimane Prefecture, specifically highlighting recommended spots in Masuda City. If you have any additional recommendations not mentioned in the video, please feel free to share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing a variety of information related to tourism, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities and experiences. For more information, check out their official social media accounts and subscribe to the channel.' where id = 'MXIKbN4ufCkXiakxtcg7A';
update content_bodies set title = '大分を観光するなら絶対見たい絶景スポット７選', description = '大分県の旅行や観光に役立つ情報を提供する動画で、絶景スポットを7つ紹介しています。動画に登場しないおすすめスポットがあれば、コメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事など、旅行をより楽しくする情報を発信しています。旅行を通じて人生を豊かにし、新しい可能性を発見することを目指しています。多くの人が旅行に出かけ、新たな体験を通じて人生を豊かにするきっかけとなることを願っています。' where id = '5_yjlaL84dZRuMP7dE7uQ';
update content_bodies set title = '7 Must-See Scenic Spots in Oita for Your Trip', description = 'This video introduces seven breathtaking scenic spots in Oita Prefecture, perfect for travelers and tourists. If you have any recommendations that are not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing various travel information, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes that travel enriches life and helps discover new possibilities. They encourage more people to travel and find new opportunities through their adventures. For more information and updates, follow their official social media accounts.' where id = 'KeI61TBPjpoIRFFrwWhJY';
update content_bodies set title = '滋賀では見逃せない王道(定番)の観光スポット７選', description = 'この動画では、滋賀県の旅行や観光に役立つ王道の観光スポットを7つ紹介しています。動画で紹介されていないおすすめがあれば、ぜひコメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事など、旅行をより楽しくする情報を提供することを目的としています。旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見することを促しています。最新情報や更新については、公式のSNSアカウントをフォローしてください。' where id = 'HWwYChs6nGvZrSHOwm5gL';
update content_bodies set title = '7 Must-See Tourist Spots in Shiga', description = 'This video introduces seven classic tourist spots in Shiga Prefecture, perfect for those planning a trip or sightseeing in the area. If you have any recommendations that are not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to provide enjoyable travel information, covering various aspects such as sightseeing, transportation, accommodation, and dining. The team believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys. For more information and updates, follow their official social media accounts.' where id = 'tQITjQPiW2H1Ve5k3XvDV';
