update content_bodies set title = 'Kozaburo Goes! Castle Town Collection No. 10 - Hikone Castle Edition', description = 'Hikone Castle, one of the 12 existing castles with original keep structures from before the Edo period, showcases the charm of both the castle and the surrounding castle town. Kozaburo from Cutie Bronze shares the appeal of this historical site.' where id = '6u0uWP6tGc-Ofqt_qQlcA';
update content_bodies set title = '高知県 仁淀川エリアPR動画「発見の夏旅編」土佐市Ver', description = 'この動画では、豊かな水を湛える仁淀川の美しさを紹介しています。夏の強い陽射しの下で水面がきらめき、周囲の環境を潤し、豊かに育んでいます。高知県の仁淀地域で新しい発見をする旅に出かけませんか？高知市からのアクセスも良好で、様々な高知の魅力を楽しむことができます。仁淀川沿いの観光スポットについての詳細は、提供されたリンクをご覧ください。' where id = 'nlubaVfwiK0jcoqjJDc1q';
