update content_bodies set title = '高知県 仁淀川エリアPR動画: 発見の夏旅編 - 越知町Ver', description = 'この動画では、高知県の美しい仁淀川を紹介しています。豊かな水が夏の強い陽射しの下できらめき、流域を潤し、活気ある環境を生み出しています。新しい体験を求めて、この美しい場所を訪れることを呼びかけています。高知市からのアクセスも良好で、様々な高知の魅力を楽しむことができます。仁淀川エリアの観光情報は、提供されたリンクからご覧いただけます。動画内では、有機高揚 ZAB体験や越知町の浅尾沈下橋などのスポットが紹介されています。' where id = 'Z4BQ-KfKLB6YxNojx1hps';
update content_bodies set title = 'Kochi Prefecture Niyodo River Area PR Video: Summer Travel Edition - Ochi Town Version', description = 'This video showcases the beautiful Niyodo River in Kochi Prefecture, where the rich waters shimmer under the strong summer sun. The river nourishes the surrounding area, creating a vibrant environment. It invites travelers to discover new experiences in this picturesque location. With easy access from Kochi City, visitors can enjoy various attractions in Kochi. For more information about tourism in the Niyodo River area, visit the provided link. The video features specific spots such as the Organic High Spirits ZAB Experience and the Asao Sinking Bridge in Ochi Town.' where id = 'Cez7gVjtDI8xBi_MK4UNP';
update content_bodies set title = '【三重県】入場無料！一面に広がるコスモス畑🌸 #kankomie #観光三重 #とことめの里一志', description = '三重県のとことめの里一志では、入場無料でコスモス畑を楽しむことができます。秋にはコスモス、夏にはヒマワリが咲き誇り、フォトスポットも豊富です。訪れた際にはコスモスが見ごろを迎えており、毎年11月上旬まで美しい花畑が広がります。見ごろが終わる前に急いで訪れてみてください。公式サイトで開花状況を確認できます。場所は津市一志町井関1792で、24時間立ち入り可能、駐車場も無料です。伊勢自動車道「一志嬉野IC」から車で約10分のアクセスです。この投稿が面白いと思ったら、ぜひ「いいね＆保存」をお願いします！' where id = 'DQwuu9OKkRoK0rek9QUCT';
update content_bodies set title = 'Free Admission! A Vast Cosmos Field in Mie Prefecture 🌸 #kankomie #TourismMie #TokotomeNoSatoIsshi', description = 'Enjoy a vast cosmos field with free admission! In autumn, cosmos flowers bloom, while sunflowers flourish in summer. This popular spot features numerous photo opportunities, including a ''Anywhere Door'' and face panels. During the visit, the cosmos were in full bloom, showcasing their beauty. The cosmos field is expected to remain vibrant until early November each year. Hurry before the peak season ends! You can check the blooming status on the official website. Location: Tokotome No Sato Isshi, 1792 Iseki, Isshi-cho, Tsu City. Open 24 hours with free parking available. Access: About 10 minutes by car from the Ise Expressway ''Isshi-Ueno IC''. If you find this post interesting, please give it a like and save it!' where id = 'vGPIBk7goumPoi_IEk3ME';
