update content_bodies set title = 'どうやって建てられた？ 断崖絶壁な越知❝聖神社❞', description = '越知の聖神社は、断崖絶壁に建てられた非常に珍しい神社であり、その独特な立地は建設方法や歴史に関する疑問を呼び起こします。神社の謎に満ちた存在は、多くの人々の興味を引きつけています。' where id = 'ltfBgOxiUZZb5ZjuTXwoc';
update content_bodies set title = 'How Was It Built? The Mysterious ''Seishin Shrine'' on a Cliff', description = 'Seishin Shrine is a very rare and mysterious shrine built on a sheer cliff. Its unique location raises questions about its construction and the history behind it.' where id = '9W94o1e3F5mKONv3iPlsm';
update content_bodies set title = '紀州備長炭 - 400年、受け継がれる火 -', description = '紀州備長炭は自然と人の営みを繋ぎます。紀北で炭の製造を学び、炭で焼き上げた美食を味わう旅を体験してみませんか。大自然本舗えむてぃと炭火割烹稲米舎があり、三重県北牟婁郡紀北町に位置しています。紀勢自動車道やJR紀勢本線を利用してアクセス可能で、両施設には駐車場も完備されています。詳細は「観光三重」のレポート記事で紹介されています。' where id = 'zc0IZqsvGJDuBfwIh8gdY';
update content_bodies set title = 'Kishu Binchotan - 400 Years of Tradition -', description = 'Kishu Binchotan connects nature and human activities. Experience a journey in Kiho where you can learn about charcoal production and savor exquisite dishes cooked with this charcoal. The locations include Daishizen Honpo MT and Sumibi Kappo Inaka, both situated in Kihoku, Mie Prefecture. They are accessible via various routes, including the Kisei Expressway and JR Kisei Line. Parking is available at both sites. For more information, you can refer to the report article on ''Kankomie'' that introduces these places.' where id = 'NiPhamsiF-iUl2x6fbvgd';
