update content_bodies set title = '紅葉と一緒に味わいたい！秋のおすすめランチ６選', description = '茨城県への旅行や観光に役立つランチスポットを紹介する動画です。動画で紹介されていないおすすめがあれば、コメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事などの旅行情報を提供し、旅行をより楽しくすることを目的としています。メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見することを促しています。公式SNSアカウントをフォローして、最新の旅行情報を受け取ることができます。' where id = '6ACnSo0T-9HOpBAdB-C_a';
update content_bodies set title = 'Recommended Autumn Lunches to Enjoy with Fall Foliage in Ibaraki', description = 'This video provides recommendations for lunch spots in Ibaraki Prefecture, perfect for travelers and tourists. If you have any additional suggestions not mentioned in the video, please share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by sharing various travel information, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys. For more updates and travel tips, you can follow their official social media accounts.' where id = 'oTj7dCNOrNM_miJng2_cR';
update content_bodies set title = '世界に誇る観光名所「伏見稲荷大社」の魅力！', description = 'この動画は、京都旅行を計画している方に向けて、伏見稲荷大社の魅力を紹介しています。動画で紹介されていないおすすめスポットがあれば、コメント欄でシェアしてほしいとのことです。「旅行の達人」チャンネルは、観光、移動、宿泊、食事など、旅行に関する情報を提供し、旅行を通じて人生を豊かにすることを目指しています。動画では、伏見稲荷大社の本殿や千本鳥居など、訪れるべきスポットが詳しく紹介されています。訪問前には公式サイトで最新情報を確認するようにとの注意もあります。' where id = 'Z1q_UAA1mQ9XpNmoRv80O';
update content_bodies set title = 'The Charm of Fushimi Inari Taisha, a World-Class Tourist Attraction in Kyoto!', description = 'This video serves as a guide for those traveling to Kyoto, specifically highlighting the attractions of Fushimi Inari Taisha. Viewers are encouraged to share their own recommendations in the comments if they have suggestions not covered in the video. The channel, ''Travel Master,'' aims to provide enjoyable travel information, covering various aspects such as sightseeing, transportation, accommodation, and dining. The mission is to enrich lives through travel, with a team that spends nearly half the year traveling. The video outlines key spots within Fushimi Inari Taisha, including the main shrine, the famous thousand torii gates, and other significant locations. Viewers are reminded to check official sources for the latest information before visiting.' where id = 'bWggTgkfmEzXb4VcEPFLr';
update content_bodies set title = '東京スカイツリーをより壮大にさせる９の歴史', description = 'この動画は東京への旅行や観光の参考として、東京スカイツリーに関する９つの歴史を紹介しています。視聴者には、動画で紹介されていないおすすめ情報をコメント欄でシェアするよう促しています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事などの情報を提供し、旅行をより楽しくすることを目的としています。運営メンバーは、旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見する手助けをしたいと考えています。公式SNSアカウントをフォローし、チャンネル登録をすることで、さらに多くの情報を得ることができます。' where id = 'n3kKmOBp1uNP4hg2hxDnj';
update content_bodies set title = '9 Historical Facts That Make Tokyo Skytree More Magnificent', description = 'This video serves as a guide for those traveling to Tokyo, presenting nine historical facts about the Tokyo Skytree. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a wealth of information on sightseeing, transportation, accommodation, and dining, both domestically and internationally. The team behind the channel believes in enriching lives through travel and aims to inspire viewers to discover new possibilities and enhance their lives through exploration. For more information, viewers can follow the official social media accounts and subscribe to the channel.' where id = 'PZzAYe7UXjMDjvr5Wot7D';
update content_bodies set title = '宮崎旅行/観光】洞窟の中にある神社「鵜戸神宮」の魅力を探索！', description = 'この動画は宮崎県への旅行や観光の参考として、鵜戸神宮の魅力を7つ紹介しています。視聴者はコメント欄で他のおすすめをシェアすることが奨励されています。「旅行の達人」チャンネルは、観光、移動、宿泊、食事などの旅行情報を提供し、旅行を通じて人生を豊かにすることを目指しています。動画では、鵜戸神宮の詳細、アクセス、神話の世界、洞窟内の本殿、運玉を使った運試し、豊玉姫に関連するお乳水、うさぎ神社としての魅力について説明されています。訪問前には公式サイトでの確認が推奨されています。' where id = '82K6K8OQIdty6NmRWVWwo';
update content_bodies set title = 'Exploring the Charm of Udo Shrine, a Cave Shrine in Miyazaki', description = 'This video serves as a guide for those traveling to Miyazaki Prefecture, highlighting seven attractions of Udo Shrine. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing various travel information, including sightseeing, transportation, accommodation, and dining. The mission is to enrich lives through travel, with a team that spends nearly half the year traveling. The video includes details about Udo Shrine, its access, mythological significance, the main hall within a cave, fortune-testing with ''un-tama'' stones, the sacred water related to Toyotama-hime, and the shrine''s connection to rabbits. For more information, viewers are advised to check official sources before visiting.' where id = 'EbYsLSe-hqREPw6on_18F';
update content_bodies set title = '【東京旅行/観光】知られざる東京タワーの魅力１０選', description = 'この動画は、東京への旅行や観光を計画している方に向けて、東京タワーの知られざる10の魅力を紹介しています。視聴者は、動画で紹介されていないおすすめ情報をコメント欄でシェアすることが奨励されています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事など、旅行をより楽しくするための情報を提供することを目的としています。メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見し、旅を楽しむことを促しています。最新情報や旅行のヒントを得るために、公式のSNSアカウントをフォローすることが推奨されています。' where id = 'bGNDNm8RduPM_TN-ZpeiX';
update content_bodies set title = '10 Hidden Charms of Tokyo Tower', description = 'This video serves as a guide for those traveling to Tokyo, highlighting ten lesser-known attractions of Tokyo Tower that offer plenty of fun and enjoyment. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to provide comprehensive travel information, including sightseeing, transportation, accommodation, and dining, to enhance the travel experience. The team believes in enriching lives through travel and aims to inspire viewers to discover new possibilities and enjoy their journeys. For more updates and travel tips, viewers can follow the official social media accounts.' where id = 'XcJdJFSC7FHKTcv6GjR0A';
update content_bodies set title = '滋賀の桃源郷「MIHO MUSEUM」とは？', description = 'この動画は滋賀県への旅行や観光を考えている方に向けて、世界的に注目されているMIHO MUSEUMの魅力を紹介しています。コメント欄で他のおすすめ情報をシェアすることも呼びかけています。「旅行の達人」チャンネルは、観光、移動、宿泊、食事などの情報を提供し、旅行をより楽しくすることを目指しています。旅行を通じて人生を豊かにし、新しい自分を発見することを促しています。動画では、MIHO MUSEUMの建築や自然、質の高いコレクション、アクセス方法、ショップやカフェについても触れています。' where id = 'pU4VSZTsrTuTS6OZsYRZz';
update content_bodies set title = 'What is MIHO MUSEUM, the Peach Blossom Land of Shiga?', description = 'This video serves as a guide for those traveling to Shiga Prefecture, highlighting the attractions of the internationally acclaimed MIHO MUSEUM. It invites viewers to share additional recommendations in the comments if they have any. The channel, ''Travel Master,'' aims to enhance travel experiences by providing comprehensive information on sightseeing, transportation, accommodation, and dining. The mission is to enrich lives through travel, encouraging people to explore new possibilities and discover themselves. The video covers details about MIHO MUSEUM, including its architectural beauty, natural surroundings, and high-quality collections. It also provides access information and mentions the museum''s shop and café.' where id = 'rTdtQkqZUsOqgnphGZN5t';
update content_bodies set title = '神話に包まれた天岩戸神社の魅力にせまる！', description = 'この動画は、宮崎県への旅行や観光を考えている方に向けて、宮崎屈指のパワースポットである天岩戸神社を紹介しています。神話の舞台としての魅力を持つこの神社について、詳細やアクセス情報、神話にまつわる話、天安河原の紹介、そして西本宮と東本宮についても触れています。また、視聴者にはコメント欄でのおすすめ情報の共有を呼びかけています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行を通じて人生を豊かにすることを目指しています。' where id = '3EfNMb4-wnWHutBkwx6dl';
update content_bodies set title = 'Exploring the Charm of Amano Iwato Shrine, Wrapped in Mythology!', description = 'This video serves as a guide for those traveling to Miyazaki Prefecture, focusing on the Amano Iwato Shrine, one of the region''s top power spots and a site steeped in mythology. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a wealth of information on sightseeing, transportation, accommodation, and dining, with a vision to enrich lives through travel. The video includes details about the shrine, access information, related myths, and the nearby Amano Iwato River, as well as the West and East Main Shrines. For more travel tips and updates, viewers can follow the channel''s official social media accounts.' where id = '2fzhGro2JXm16gA4AjiIv';
update content_bodies set title = '【みえのイマココ旅】古代の人々になりきり墨書土器体験', description = '「みえのイマココ旅」では、王朝ロマンのまち斎宮での歴史体験を提供します。5歳以上の方が参加でき、奈良時代の天平衣装を着て斎宮周辺の古墳を散策します。参加者は自分だけの文字や絵を描いた墨書土器を作成し、記念に「御墳印」を受け取ることができます。料金はおひとり¥2,500で、斎宮歴史博物館内のカフェスペースで行われます。アクセスは近鉄「斎宮駅」から徒歩約15分、伊勢自動車道「玉城IC」から北へ約20分です。「みえのイマココ旅」は、三重のユニークな体験を楽しむことを目的としています。' where id = 'kC86r1NHOGZj-dtCwCNdH';
update content_bodies set title = 'Experience Ancient Life with Inked Pottery in Saiku', description = 'Join the ''Mie no Imakoko Tabi'' for a unique historical experience in the romantic town of Saiku. Participants of all ages, from 5 years old to adults, can dress in Nara period Tenpyo costumes and explore the ancient burial mounds in the area. The experience includes creating your own inked pottery with personalized designs and receiving a commemorative ''Gofun-in'' stamp as a keepsake. The event costs ¥2,500 per person and takes place at the café space within the Saiku Historical Museum. Access is convenient, with a 15-minute walk from Saiku Station or a 20-minute drive from Tamaki IC on the Ise Expressway. ''Mie no Imakoko Tabi'' aims to offer unique experiences that highlight the best of Mie Prefecture.' where id = 'jqopHfG4Y6TacbChcH8D4';
update content_bodies set title = '愛知県のオススメ観光スポット15選', description = '愛知県への旅行を計画している方に向けて、オススメの観光スポットを15カ所紹介する動画です。動画で紹介されていないスポットがあれば、ぜひコメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事など、旅行に関するさまざまな情報を提供し、視聴者の旅行体験をより豊かにすることを目指しています。運営チームは、旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見することを奨励しています。最新情報や旅行のヒントを得るために、公式のSNSアカウントをフォローすることもできます。' where id = 'nLKJvc8fd5V3JFJpqdc4L';
update content_bodies set title = 'Recommended Tourist Spots in Aichi Prefecture: 15 Selections', description = 'This video serves as a guide for those planning to travel to Aichi Prefecture, presenting 15 recommended tourist spots. If you have any additional recommendations not mentioned in the video, please feel free to share them in the comments section. The channel, ''Travel Master,'' aims to enhance your travel experience by providing various travel information, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys. For more updates and travel tips, you can follow their official social media accounts.' where id = 'MbqLS0mYv8zQ45lR67ORo';
update content_bodies set title = '福島おすすめ景勝地：泊まりたいホテル10選！', description = '福島県への旅行や観光を計画している方に向けて、裏磐梯観光協会とのコラボレーションで、裏磐梯のおすすめホテル10選を紹介する動画です。視聴者には、コメント欄で自分のおすすめをシェアするよう促しています。このチャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行を通じて人生を豊かにすることを目指しています。動画では各ホテルの詳細と位置情報へのリンクも含まれており、訪問前に公式サイトで最新情報を確認するようにとの注意喚起もされています。' where id = 'k11FrJhMmK-1C_qn9w2I5';
update content_bodies set title = 'Top 10 Hotels to Stay in Urabandai, Fukushima', description = 'This video serves as a guide for those planning to travel to Fukushima Prefecture, showcasing ten recommended hotels in Urabandai in collaboration with the Urabandai Tourism Association. Viewers are encouraged to share their own recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a wealth of information on sightseeing, transportation, accommodation, and dining, with a vision to enrich lives through travel. The video includes details about each hotel, along with links to their locations. Viewers are advised to check official websites for the most current information before visiting.' where id = 'Z2yBW2jhN0b-nY5e_Dw3G';
update content_bodies set title = '三重県の美味しい！ヘルシー！が盛りだくさん「高野尾花街道 朝津味」', description = '三重県最大のファーマーズマーケット「高野尾花街道 朝津味」では、採れたての農作物や地元の新鮮な食材を使った惣菜やお菓子が販売されています。フードコートや各種イベントもあり、訪れる人々に楽しさを提供しています。所在地は三重県津市高野尾町5680番地で、営業時間は9:30から17:00まで、木曜日は定休日です。アクセスは、伊勢自動車道「芸濃IC」から車で約5分、または津駅からのバス利用が可能ですが、バスは土日祝日のみの運行です。詳細は観光三重のウェブサイトをご覧ください。' where id = '99pXsXCZrnLFM7G5x_rEh';
update content_bodies set title = 'Delicious and Healthy! A Lot of Offerings at Takayao Hanakaido Asatsumi in Mie Prefecture', description = 'Takayao Hanakaido Asatsumi is the largest farmers'' market in Mie Prefecture, offering fresh produce and local ingredients, as well as side dishes and sweets. The market features a food court and various events, ensuring a fun experience for visitors. Located at 5680 Takayao-cho, Tsu City, Mie Prefecture, it operates from 9:30 AM to 5:00 PM, closed on Thursdays. Access is convenient by car, approximately 5 minutes from the Geino IC on the Ise Expressway, or by public transport from Tsu Station, with bus services available on weekends and holidays. For more details, visit the Mie Tourism website.' where id = 'u22K53SIRqRT0F6uUhX9r';
update content_bodies set title = '＼究極の炒飯が食べられる中華ダイニング 天山／', description = '四日市の『中華ダイニング 天山』では、味、ボリューム、コストパフォーマンスに優れた絶品の炒飯が楽しめます。大将が最高の味を追求した究極の炒飯は、さくらポークの背脂を使用しており、特におすすめです。また、さっぱりとした梅しそトンテキもあり、こちらもさくらポークを使った美味しいお肉が味わえます。詳細は観光三重トピックスをご覧ください。' where id = 'Z03t8w1l-dw_mXMCl8d4j';
update content_bodies set title = 'Ultimate Fried Rice at Chinese Dining Tenzan', description = 'Chinese Dining Tenzan in Yokkaichi is a must-visit for food lovers, offering delicious, hearty, and cost-effective fried rice. The ultimate fried rice is made with Sakura pork back fat, crafted by the chef for the best flavor. Additionally, they serve a refreshing Ume Shiso Tonteki, also made with Sakura pork, providing a delightful meat experience. For more details, visit the Mie Tourism Topics page.' where id = 'eWU7Q9GRkT4XFtfJHhurN';
update content_bodies set title = '【広島 観光】広島・宮島で訪れたい観光スポット15選', description = 'この動画は、広島県への旅行を計画している方々に向けて、世界遺産にも登録されている宮島を紹介しています。宮島は「神聖な島」として知られ、古くから多くの人々に祀られてきた場所です。世界中から多くの観光客が訪れるこの島で、特におすすめの観光スポットを15か所紹介しています。視聴者には、動画で紹介されていないおすすめスポットをコメント欄でシェアするよう呼びかけています。また、旅行の達人チャンネルは、観光、宿泊、食事など、旅行に関する情報を幅広く提供し、旅行をより楽しくすることを目指しています。' where id = 'DPmz-q6KP6QZo6tPMEy2Z';
update content_bodies set title = '15 Must-Visit Tourist Spots in Hiroshima and Miyajima', description = 'This video serves as a guide for those planning to travel to Hiroshima Prefecture, highlighting Miyajima, a UNESCO World Heritage site known as a ''sacred island.'' With its rich history and cultural significance, Miyajima attracts numerous tourists from around the world. The video presents 15 recommended tourist spots on the island, including famous landmarks and local attractions. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing comprehensive information on various aspects of travel, including sightseeing, accommodation, and dining.' where id = 'iF_Ea1rphuG9hg83DMMZP';
update content_bodies set title = '【北海道ニセコご招待キャンペーン】10月のニセコでワーケーション体験キャンペーンご説明！無料で3組ご招待！', description = 'このチャンネルは、北海道ニセコエリアの倶知安観光協会が運営し、サマーステイを推奨しています。今回の動画では、Instagramで実施中の『秋のニセコでワーケーションEnjoy』キャンペーンについて説明しています。内容はキャンペーンの概要、応募方法、注意点が含まれています。ニセコエリアは冬が有名ですが、夏も魅力的であることを伝えるためにチャンネルを開設しました。今後も動画をアップしていく予定で、チャンネル登録を促しています。' where id = 'dQZ_VddtZkCKczlvFd44y';
update content_bodies set title = 'Niseko Hokkaido Invitation Campaign: Experience Workation in October! Free Invitation for 3 Groups!', description = 'This channel promotes summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. The video introduces the ''Enjoy Workation in Autumn Niseko'' campaign currently running on Instagram. It includes details about the campaign, application methods, and important notes. The campaign aims to highlight the summer attractions of the Niseko area, which is famous for winter but also offers great experiences in summer. Viewers are encouraged to subscribe for more videos showcasing the summer charm of Niseko.' where id = 'EKTclB8BVq5Ng7oNPjRHK';
update content_bodies set title = '北海道ニセコ「ニセコオータムフードフェスティバル2020」イベントご紹介', description = 'このチャンネルは、北海道ニセコエリアの倶知安観光協会が運営し、サマーステイを推奨しています。2020年9月17日から5日間開催される『ニセコオータムフードフェスティバル2020』を紹介する動画では、イベントの内容や感染症対策、お得な宿泊情報が含まれています。撮影場所はMUSE Nisekoで、ニセコは冬だけでなく夏も魅力的な観光地であることを伝えています。今後も動画をアップする予定で、視聴者にチャンネル登録を促しています。' where id = 'k61_lWnSB8dvP0yMZx8mo';
update content_bodies set title = 'Niseko Autumn Food Festival 2020 Introduction | Staycation in Niseko, Hokkaido', description = 'This channel recommends summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. The video introduces the ''Niseko Autumn Food Festival 2020'', which will be held for five days starting from September 17, 2020. It covers the festival''s details, infection control measures, and accommodation deals. The filming location is MUSE Niseko. While Niseko is famous for winter, summer in the area is also highly recommended. The channel aims to showcase the charm of summer in Niseko and plans to upload more videos, encouraging viewers to subscribe.' where id = 'uaQDwtOlprLJq05r6aCgr';
update content_bodies set title = 'JR関西線12駅途中下車の旅', description = '俳優の松田昇大さんが案内役となり、JR関西線の「関駅」と「伊賀上野駅」を途中下車しながら、観光名所や地域のスポット、おいしいお菓子や食事を紹介するPRムービーです。まち歩きの様子は「観光三重」でも紹介されています。令和6年11月1日から、JR関西線の12駅（亀山駅～加茂駅）で途中下車できる企画きっぷが販売され、沿線のお店で使えるクーポンもセットになっています。チケットは日本旅行の予約サイトで購入可能です。' where id = 'Lv5S3diPED1pA05xb2YqW';
update content_bodies set title = 'Journey of Getting Off at 12 Stations on the JR Kansai Line', description = 'In this promotional video, actor Shodai Matsuda serves as the guide for a leisurely town walk along the JR Kansai Line. The journey features stops at ''Seki Station'' and ''Iga Ueno Station,'' showcasing local attractions, regional spots, and delicious snacks and meals. The walking tour is also featured on ''Tourism Mie.'' Starting November 1, 2024, a special ticket will be available, allowing travelers to get off at any of the 12 stations along the JR Kansai Line (from Kameyama Station to Kamo Station) and includes coupons for use at local shops. Tickets can be purchased through Japan Travel''s reservation site.' where id = 'Td1jw42tWZBxjBlTGq8qs';
update content_bodies set title = '大江戸温泉物語Premium伊勢志摩', description = '三重県志摩市にある「大江戸温泉物語Premium伊勢志摩」がリニューアルオープンしました。プレミアムラウンジではアルコールを含むドリンクが無料で提供され、英虞湾を望む絶景の露天風呂が楽しめます。また、海の幸をふんだんに使ったバイキングが自慢の和モダンな温泉宿です。伊勢志摩観光の際には、「大江戸温泉物語Premium伊勢志摩」での宿泊が最適です。詳細は観光三重のウェブサイトで紹介されています。' where id = 'NfekSBbTwFcPHnOAaLszg';
update content_bodies set title = 'Oedo Onsen Monogatari Premium Ise-Shima', description = 'I visited the newly renovated ''Oedo Onsen Monogatari Premium Ise-Shima'' located in Shima City, Mie Prefecture. The premium lounge offers complimentary alcoholic drinks, and guests can enjoy a stunning open-air bath overlooking Ago Bay. The hotel is known for its seafood buffet and features a modern Japanese-style onsen accommodation. For those looking to stay in Ise-Shima for sightseeing, ''Oedo Onsen Monogatari Premium Ise-Shima'' is the perfect choice. More details can be found on the Kankomie website.' where id = 'V-_wejXY6zqSav16eK79A';
update content_bodies set title = 'オーガニックにこだわったお茶屋さんが手がけるカフェ「kikicha cafe」', description = '三重県多気郡大台町に2023年秋にオープンした「kikicha cafe」は、全国で3位の茶栽培面積と生産量を誇る三重県に位置しています。このカフェは、有機無農薬でお茶を栽培する生産者が運営しており、特に2種類のお茶のパフェが観光三重のトピックスで紹介されています。カフェの住所は三重県多気郡大台町栃原1127-2で、営業時間は10:00から17:00（L.O 16:30）で不定休です。駐車場は約10台分あり、伊勢自動車道「勢和多気IC」から車で8分のアクセスが可能です。' where id = '0aEzb6EY3Sau6j3zSaQ71';
update content_bodies set title = 'Kikicha Cafe: A Tea Shop Focused on Organic Practices', description = 'Kikicha Cafe, located in Odaicho, Mie Prefecture, which ranks third in Japan for tea cultivation area and production, opened in the fall of 2023. This cafe is run by producers who cultivate tea organically and without pesticides. The cafe features two types of tea parfaits made with dedication, highlighted in a tourism topic by Kankomie. For more details, visit their website. The cafe is situated at 1127-2 Tochihara, Odaicho, Mie, and is open from 10:00 AM to 5:00 PM, with last orders at 4:30 PM. It has irregular holidays and parking for about 10 cars. Access is convenient, being an 8-minute drive from the Seiwa-Taki IC on the Ise Expressway.' where id = '5YiNmkUxYCWBU_YRUeDFf';
update content_bodies set title = '和歌山グルメ最強コスパ！誰もが驚く絶品ランチ＆ディナー8選', description = 'この動画は和歌山県を訪れる旅行者のためのガイドで、コストパフォーマンスに優れた絶品ランチとディナーのスポット8選を紹介しています。視聴者には、他のおすすめがあればコメント欄でシェアするよう呼びかけています。チャンネル「旅行の達人」は、観光、宿泊、食事など、旅行に関するさまざまな情報を提供し、旅行をより楽しくすることを目指しています。メンバーは旅行を通じて人生を豊かにすることを信じており、新しい可能性を発見するために旅に出ることを奨励しています。' where id = 'B5saC-XW1TI8mRP7FrXb4';
update content_bodies set title = 'Wakayama Gourmet: 8 Amazing Lunch and Dinner Spots with Great Cost Performance', description = 'This video serves as a guide for those traveling to Wakayama Prefecture, showcasing eight recommended lunch and dinner spots known for their excellent cost performance. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a wealth of information on various travel aspects, including sightseeing, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys.' where id = '3Nj4MBPDIbEBW-ldAOnoa';
update content_bodies set title = '宮城の人気観光おすすめ8選', description = 'この動画では、宮城県の人気観光スポットを紹介しています。旅行や観光の参考にしてください。動画で紹介されていないおすすめがあれば、コメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事などの旅行情報を提供し、旅行をより楽しくすることを目指しています。メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見することを促しています。最新情報は公式SNSでフォローしてください。' where id = 'Dka296pnhpPSJyuIH9Lum';
update content_bodies set title = 'Top 8 Must-Visit Tourist Spots in Miyagi', description = 'This video provides a guide to popular tourist attractions in Miyagi Prefecture, perfect for planning your trip. If you have any additional recommendations not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by sharing various travel information, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities. For more information and updates, follow their official social media accounts.' where id = 'jKy1ysT78eJ3IGfq3JZgO';
update content_bodies set title = '【かごしま】⑥秘密の展望台で、お醤油愛をさけぶ！', description = 'このエピソードでは、秘密の展望所「サクラカネヨの杜」を訪れ、素晴らしい眺めを楽しみながら、鹿児島の豊かな自然が美味しくて甘いお醤油の生産に寄与していることを学びます。小学生たちは、鹿児島のお醤油がなぜ甘いのかという疑問を持ち、地元の人々と交流しながら、郷土の食文化や自然、歴史を探求します。この取り組みは「かごしまこどもプランナー」と呼ばれ、COVID-19の影響で子どもたちが自ら考える機会を持つために立ち上げられました。お醤油に関するさまざまなエピソードが制作され、YouTubeチャンネルで視聴可能です。' where id = '0BLOC2LHt24kQKxssY6mQ';
update content_bodies set title = 'Kagoshima: Shouting Love for Soy Sauce at a Secret Observation Deck!', description = 'In this episode featuring the secret observation spot ''Sakura Kaneyo no Mori'', we discover a stunning view and learn about the rich nature of Kagoshima, which contributes to the production of delicious and sweet soy sauce. The children, curious about why Kagoshima''s soy sauce is sweet, engage with local residents to explore the region''s food, culture, nature, and history through the theme of soy sauce. This initiative, called ''Kagoshima Children Planner'', was created during the COVID-19 pandemic to encourage children to think about what they can do, leading to the production of this video. The project includes various episodes focusing on different aspects of soy sauce, all available on their YouTube channel.' where id = 'kb57RygunxzqXUSq7NwLS';
update content_bodies set title = '【いちき串木野市】Vol.1 冠岳花川砂防公園上流編【エアお花見】', description = 'いちき串木野市の桜の開花情報をお届けします。冠岳花川砂防公園上流の桜を撮影した写真が含まれています。おうち時間を楽しむためのエアお花見の提案です。' where id = 'gUZJg3cOa3y5RVa708Cb_';
update content_bodies set title = 'Ichiki-Kushikino City: Vol.1 Kanmuri-dake Hanakawa Sabo Park Upstream Edition - Virtual Cherry Blossom Viewing', description = 'This is the cherry blossom blooming information for Ichiki-Kushikino City. Photos of the cherry blossoms at the upstream of Kanmuri-dake Hanakawa Sabo Park have been taken.' where id = '8GiZQACPwqVXnylTj6w-U';
update content_bodies set title = '女木島　極上の風が吹く', description = '女木島は高松港からフェリーでわずか20分の距離にある小さな島です。港に到着すると、訪れる人々を優しく迎える風を感じるアートがあります。島のほぼ中央には大きな洞窟がある山があり、これが「鬼ヶ島」と呼ばれる由縁です。展望台からは瀬戸内海の大パノラマを楽しむことができ、吹く風が心を軽くしてくれます。' where id = 'VjbigCB_urAboUls4QZNg';
update content_bodies set title = 'Megijima: A Breeze of Excellence', description = 'Megijima is a small island just 20 minutes by ferry from Takamatsu Port. Upon arrival, visitors are greeted by art that embodies the gentle breeze of the island. At the center of the island lies a mountain with a large cave, which is the reason it is also known as ''Oni Island.'' From the observation deck, one can enjoy a panoramic view of the Seto Inland Sea, where the refreshing winds uplift the spirit.' where id = 'o4nBtvGPkH-1feGySgbMP';
update content_bodies set title = '北茨城の【い】：いたるところでアートを感じる！（ニューヨーカーが北茨城の魅力を『あいうえお作文』で紹介してみた！）', description = '北茨城市は、近代日本美術の発展に大きな功績を残した岡倉天心のゆかりの地であり、岡倉天心美術館や六角堂など、アートを体感できる施設が充実しています。在日ニューヨーカーが『あいうえお作文』を通じて、北茨城の魅力を紹介しています。内容は、記憶に残るキャンパー王国、体験要素が満載で一日中楽しめること、いたるところでアートを感じられること、爆浴温泉タウン、来世でも食べたい絶品グルメ、期待以上の絶景が自慢の北茨城市です。' where id = 'UYyLEUJjaNqcdEoQ2k826';
update content_bodies set title = 'Art Everywhere in Kitaibaraki! (A New Yorker Introduces the Charm of Kitaibaraki through ''A-I-U-E-O'' Poem!)', description = 'Kitaibaraki City is a significant place in the development of modern Japanese art, closely associated with the renowned artist Okakura Tenshin. The city boasts various facilities where visitors can experience art, including the Okakura Tenshin Museum and the Rokkakudo, which served as Tenshin''s base of activities. A New Yorker, who feels that ''Japanese people who don''t know about Kitaibaraki are missing out,'' introduces the city''s attractions through an ''A-I-U-E-O'' poem. Highlights include a memorable camping kingdom, a fun-filled experience for a whole day, art felt everywhere, a hot spring town, exquisite gourmet food that one would want to eat in the next life, and breathtaking views that exceed expectations.' where id = 'DCVA43hmVgFwKyyPU7afo';
update content_bodies set title = '35,000体のフィギュアがある日本唯一の博物館！', description = '多気町にある「万協フィギュア博物館」は、万協製薬株式会社の工場内に位置し、アニメや特撮ヒーロー、プラモデル、ドール、ミリタリー、海外ものなど、35,000体以上のフィギュアを展示しています。この博物館は大人も子供も夢中になれる、まるで夢のような場所です。詳細は観光三重トピックスをご覧ください。博物館の住所は三重県多気郡多気町仁田725－1（万協製薬株式会社 第三工場内）で、営業時間は平日9:00～17:30、日・祝10:00～17:00、毎週土曜日は定休日です。入場料は1,000円（2歳未満は無料）、駐車場は無料です。' where id = 'UpAIQySiYc3il91r1-enQ';
update content_bodies set title = 'The Only Museum in Japan with 35,000 Figures!', description = 'The Mankyo Figure Museum, located in Taki Town, is situated within the Mankyo Pharmaceutical Company factory. It showcases over 35,000 figures, including anime, special effects heroes, plastic models, dolls, military items, and international figures. This museum is a dreamlike place that captivates both adults and children alike! For more details, please visit the Kankomie tourism topics page. The museum''s address is 725-1 Nita, Taki Town, Mie Prefecture, 519-2179, inside the Mankyo Pharmaceutical Company''s third factory. Opening hours are weekdays from 9:00 AM to 5:30 PM and on Sundays and holidays from 10:00 AM to 5:00 PM. It is closed every Saturday. Admission is 1,000 yen (free for children under 2 years old), and parking is free.' where id = '1meBOo-hN0kP1DDJYZxXI';
update content_bodies set title = 'たまご食べ放題！平飼い有精卵でおなじみ「コケコッコー共和国」', description = '「コケコッコー共和国」の直営店「山の駅 よって亭」では、鶏舎のすぐ近くで、驚きのたまご食べ放題を楽しむことができます。特に「たまごかけごはん」と、超お値打ちな鶏焼き肉のバーベキューが人気です。VISONから車で5分の距離にあり、グルメ好きにはたまらないスポットです。 

📍コケコッコー共和国「山の駅 よって亭」 
場所：三重県多気郡多気町丹生4409 
電話番号：0598-49-2039 
定休日：火曜日（祝日を除く） 
営業時間：10：00～17：00 
駐車場：あり（24台） 
アクセス：伊勢自動車道「勢和多気IC」から車で5分。 

観光三重トピックスでさらに詳しく紹介していますので、ぜひご覧ください。' where id = 'OMZ9iJYWKOt6vvIr_bH4m';
update content_bodies set title = 'All-You-Can-Eat Eggs! Famous for Free-Range Fertilized Eggs at ''Kokekokko Republic''', description = 'At the directly managed restaurant ''Yotte-tei'' near the chicken coop, you can enjoy an amazing all-you-can-eat egg experience with ''tamago kake gohan'' (rice with raw egg) and incredibly affordable grilled chicken barbecue. Located just a 5-minute drive from VISON, this popular spot offers great gourmet options. 

📍 Kokekokko Republic ''Yotte-tei'' 
Location: 4409 Nyu, Taki-cho, Taki-gun, Mie Prefecture 
Phone: 0598-49-2039 
Closed: Tuesdays (except holidays) 
Hours: 10:00 AM - 5:00 PM 
Parking: Available for 24 cars 
Access: 5 minutes by car from Ise Expressway ''Seiwa-Taki IC''. 

For more details, check out the Mie Tourism Topics!' where id = 'qhxZxIo2JObFi5m3b_Vnm';
update content_bodies set title = '【茨城県北茨城市】遊休資産対象地(売却・借地)', description = 'この物件は、茨城県観光物産課と北茨城市商工観光課が管理する遊休資産活用申請地です。所在地は北茨城市磯原町磯原2553-3,5,12,13,122,127,128です。この地域は波が穏やかで、SUP初心者体験に最適な場所として知られています。また、新たに堤防が設置され、サイクリングステーションの拠点としても優れた立地です。敷地は国道6号に面しています。' where id = 'iMCbemBgTHNPzuSXYehok';
update content_bodies set title = 'Vacant Land for Sale or Lease in Kitakami City, Ibaraki Prefecture', description = 'This is a vacant land application site managed by the Ibaraki Prefecture Tourism and Products Division and the Kitakami City Commerce and Tourism Division. The location is at 2553-3, 5, 12, 13, 122, 127, 128 Isohara-cho, Kitakami City. It is well-known locally for having calm waves, making it an ideal spot for beginner SUP experiences. Additionally, new embankments have been constructed, providing an excellent base for cycling stations. The property is situated right in front of National Route 6.' where id = 'dFB5vqpRjFx9a_OdhPude';
update content_bodies set title = '伊勢で発見！カワイイ&美味しい宝庫', description = '伊勢神宮を訪れるなら、絶対に立ち寄りたいのが伊勢の魅力的で美味しいスポットです。おはらい町やおかげ横丁では、伊勢うどんや赤福、コロッケなどの地元の名物を楽しむことができます。食べ歩きやお土産探しに最適な場所です。また、三重県は絶景も豊富で、観光にもぴったりのエリアです。ぜひフォローして、さらに多くの情報をチェックしてください！' where id = 'ahML9A1Tut3RcFS3wxNvE';
update content_bodies set title = 'Found in Ise! Cute & Delicious Treasure Trove', description = 'Ise is a must-visit destination, especially if you''re heading to Ise Jingu. The area is known for its charming and delicious offerings, including local specialties like Ise udon, Akafuku sweets, and croquettes. The vibrant streets of Oharaimachi and Okage Yokocho are perfect for food lovers and those looking for souvenirs. Mie Prefecture is also celebrated for its stunning views, making it a great travel destination. Don''t forget to follow for more insights into this beautiful region!' where id = '8YoRs5MPv22IV4rCoADUL';
update content_bodies set title = '三重県で2泊3日の卒業旅行💛3日目', description = '地元大学生におすすめの三重県での卒業旅行プランを紹介します！伊勢志摩を満喫する2泊3日のスケジュールです。1日目はしまかぜに乗車し、かつおの天ぱく、大王埼灯台、志摩地中海村を訪れます。2日目は志摩スペイン村と賢島宝生苑を楽しみ、3日目には横山展望台、伊勢神宮、おかげ横丁を巡ります。詳細は観光三重のウェブサイトをご覧ください！' where id = 'ko3jil2ywLR_FsfsAC6Gk';
update content_bodies set title = 'Graduation Trip in Mie Prefecture: Day 3', description = 'This is a recommended graduation trip plan for local university students in Mie Prefecture! Enjoy a 2-night, 3-day itinerary in Ise-Shima. The schedule includes: Day 1 - riding the Shimakaze train, visiting Katsuo no Tenpaku, Daiozaki Lighthouse, and Shima Mediterranean Village; Day 2 - exploring Shima Spain Village and Kashikojima Hojoen; Day 3 - visiting Yokoyama Observatory, Ise Jingu Shrine, and Okage Yokocho. For more details, visit Kankomie!' where id = 'Osw6BGJ2QWNT3dxpBmHs6';
update content_bodies set title = '三重県で2泊3日の卒業旅行💘2日目', description = '地元大学生が提案する三重県での卒業旅行のおすすめプランです。これは2泊3日の旅行の2日目に焦点を当てています。1日目はしまかぜに乗車し、かつおの天ぱく、大王埼灯台、志摩地中海村を訪れました。2日目は志摩スペイン村と賢島宝生苑を楽しむ予定です。3日目には横山展望台、伊勢神宮、おかげ横丁を訪れる計画です。詳細は観光三重のウェブサイトをご覧ください。' where id = 'G-sGEjpzrz1cEjn4LRy7l';
update content_bodies set title = '2-Day Itinerary for a Graduation Trip in Mie Prefecture 💘 Day 2', description = 'This is a recommended itinerary for a graduation trip in Mie Prefecture, presented by local university students. This summary focuses on the second day of a 2-night, 3-day trip. The first day includes riding the Shimakaze train, visiting Katsuo no Tenpaku, Daiozaki Lighthouse, and Shima Mediterranean Village. The second day features Shima Spain Village and Kashikojima Hojoen. The third day includes Yokoyama Observatory, Ise Jingu Shrine, and Okage Yokocho. For more details, visit the Mie Tourism website.' where id = 'EX3cY9AkCpyNBUB_9laSo';
update content_bodies set title = '三重グランピング　～自然と調和した、贅沢な休日を～', description = 'グランピングとは、「グラマラス」と「キャンピング」を組み合わせた言葉です。三重の豊かな自然の中で、広々としたテントやヴィラに宿泊し、豪華な食材を使ったBBQを楽しむことができます。海、山、森に囲まれた環境で、気軽に魅力的なキャンプ体験を満喫してみませんか。' where id = 'kKj4uZhUoimosyW6Piu-k';
update content_bodies set title = 'Mie Glamping - A Luxurious Holiday in Harmony with Nature', description = 'Glamping is a blend of ''Glamorous'' and ''Camping.'' In Mie, you can enjoy this unique camping experience amidst rich natural surroundings, including the sea, mountains, and forests. Stay in spacious tents or villas and indulge in luxurious BBQs with high-quality ingredients. Experience the charm of glamping in Mie''s beautiful landscapes.' where id = 'Bomt-yk3TtX6w-6Ho5Qrn';
update content_bodies set title = '極上の休息を。三重県', description = '三重県を訪れると、心が感動と安らぎで満たされます。歴史や文化が息づくこの地では、豊かな自然とその恵みを活かした美食が楽しめます。三重には多様な魅力が揃っており、訪れる人々を癒してくれることでしょう。心の求めに応じて、それぞれ特色ある地域を訪れてみてください。' where id = 'T4ZgYKTC0AIRXfkw8qZuJ';
update content_bodies set title = 'Ultimate Relaxation in Mie Prefecture', description = 'Experience a blend of history and nature in Mie. Once you visit, your heart will be filled with emotion and tranquility. Mie offers a rich tapestry of history and culture, along with abundant natural beauty and exquisite cuisine. The diverse attractions in Mie are sure to provide you with healing and relaxation. We encourage you to explore the unique regions that cater to your heart''s desires.' where id = '0OlIP2d0D4yL28XF2Kd40';
update content_bodies set title = 'とこしえの祈りを込めて　～「持続可能な観光地」三重～', description = '三重県は日本列島のほぼ中央に位置し、伊勢湾や熊野灘に面した自然豊かな環境を有しています。さらに、二千年の歴史を持つ伊勢神宮や、鳥羽志摩の海女など、伝統文化も大切にされています。「持続可能」という言葉が注目される中、三重の自然や文化は当たり前に守られてきた宝物です。先人たちの想いが込められた三重の美しい自然や伝統を未来へ繋ぐために、ぜひ訪れてみてください。' where id = 'ZXLk8IKdeO12adHFFb-xp';
update content_bodies set title = 'Eternal Prayers: Mie as a Sustainable Tourism Destination', description = 'Mie Prefecture, located in the central part of Japan, is blessed with a rich natural environment, featuring the Ise Bay, Kumano-nada Sea, and mountain ranges like the Suzuka and Kii Mountains. It is also home to the Ise Jingu, a spiritual heart of Japan with a history spanning over two millennia, and the traditional Ama divers of Toba and Shima. The concept of ''sustainability'' has gained prominence in recent years, yet the natural beauty and cultural heritage of Mie have been preserved as invaluable treasures. The desire to protect Mie''s beautiful nature and esteemed traditions for future generations is deeply rooted in the aspirations of its ancestors. Consider visiting Mie, a ''sustainable tourism destination'' that embodies these eternal prayers.' where id = 'gTbJdf-uSrcVWyTUb_aym';
update content_bodies set title = '三多気の桜【ドローン撮影】(津市)｜観光三重｜三重県の観光・旅行情報', description = '津市美杉町の三多気の桜並木をドローンで撮影した映像です。ここは「日本さくら名所100選」に選ばれており、500本以上の古木のヤマザクラが並ぶ道が、伊勢本街道から真福院までの1.5kmにわたって続いています。まるで桜のトンネルをくぐるような美しい景観が広がっています。' where id = 'fQfhq6ABoMjEJoxIphUVu';
update content_bodies set title = 'Sakura at Santaki [Drone Footage] (Tsu City) | Tourism Mie | Mie Prefecture Travel Information', description = 'This video features drone footage of the cherry blossom avenue at Santaki in Misugi Town, Tsu City, which is selected as one of Japan''s 100 Famous Cherry Blossom Spots. The avenue, lined with over 500 ancient Yamazakura trees, stretches 1.5 kilometers from Ise Honkaido to Shinpukuin, creating a stunning cherry blossom tunnel.' where id = 'q8Y30O285ZU6p_x_qyKif';
update content_bodies set title = 'みえのイマココ旅　「絶景×アクティビティ」編', description = '「みえのイマココ旅」は、三重の「イマしかない」「ココしかない」体験を楽しむことを目的とした旅行プランです。テーマは「自然」「歴史・文化」「伝統」「ものづくり」「食」「ナイト＆モーニング」「サスティナブル」で、特設サイトでは50以上の体験プランが紹介され、予約が可能です。「絶景」×「アクティビティ」では、尾鷲のオハイブルーや大台町でのツリークライミング、大紀町での洞窟探検など、三重県の魅力的な体験が紹介されています。動画では、熊野川のパックラフトツアーや九木崎の絶景散策、木の上からの景色を楽しむツリークライミング、宮川のカヌーツーリング、自然の鍾乳洞での洞窟探検などが登場します。' where id = 'oItS5ukVEhihN66l3di4b';
update content_bodies set title = 'Mie Imakoko Travel: ''Scenery × Activity'' Edition', description = 'Mie Imakoko Travel invites visitors to experience unique moments in Mie, focusing on ''nature,'' ''history and culture,'' ''tradition,'' ''craftsmanship,'' ''food,'' ''night and morning,'' and ''sustainability.'' The special site features over 50 experience plans that can be reserved, showcasing a new form of travel. The ''Scenery × Activity'' section highlights special experiences in Mie, such as the stunning Ohai Blue in Owase, tree climbing in Odaicho, and cave exploration in Daiki Town. The video introduces various spots, including a packraft day camp tour on the Kumano River, a scenic walk in Kuki Town, a tree climbing experience in Odaicho, canoe touring on the Miyagawa River, and a cave exploration in Daiki Town.' where id = 'vJnuUJHQAstMBTEt_b4UU';
update content_bodies set title = 'みえのイマココ旅　「歴史×文化」編', description = '「みえのイマココ旅」は、三重の「イマしかない」「ココしかない」体験を楽しむことを目的とした旅行プランです。「自然」「歴史・文化」「伝統」「ものづくり」「食」「ナイト＆モーニング」「サスティナブル」をテーマに、50以上の体験プランを特設サイトで紹介し、予約が可能です。歴史と文化に焦点を当てたプランには、明和町での墨書土器体験を含む古墳散策や、伊賀の醤油醸造蔵見学、尾鷲での熊野古道を巡る特別プランなどがあります。動画では、名張市のプライベートツアーや、古代装束体験、伊賀市の醤油蔵見学など、さまざまなスポットが紹介されています。' where id = 'WMSEHsiK2vuC8onPMCRQh';
update content_bodies set title = 'Mie Imakoko Travel: History x Culture Edition', description = 'Mie Imakoko Travel invites visitors to experience unique aspects of Mie Prefecture, focusing on ''nature,'' ''history and culture,'' ''tradition,'' ''craftsmanship,'' ''food,'' ''night and morning,'' and ''sustainability.'' The special site features over 50 experiential plans that can be reserved, showcasing activities such as ancient burial mound walks with pottery writing experiences in Meiwa Town, visits to a soy sauce brewery in Iga that has been operating since the Meiji era, and a special plan exploring the Kumano Kodo trails in Owase. The video highlights various spots, including a private tour in Nabari, ancient clothing experiences in Meiwa, and a time-traveling visit to a century-old soy sauce brewery in Iga.' where id = 's39xfb7TyaNuQjuPt15yl';
update content_bodies set title = '岡山ナゾトキミステリー〜歴史探偵と烏城の謎〜　オープニングムービー', description = 'ある日、岡山城で巻物が見つかりました。その巻物には岡山城に関する謎が記されていました。あなたは時を旅する“歴史探偵”となり、岡山城の謎に挑戦することになります。松丸亮吾からのメッセージもあり、巻物に記された謎に挑むことが求められています。' where id = '3CgGq5b3Z5Bl5HJJEvywf';
update content_bodies set title = 'Okayama Mystery Solving - The Historical Detective and the Mystery of Okayama Castle - Opening Movie', description = 'One day, a scroll was discovered at Okayama Castle. It contained mysteries related to the castle. As a time-traveling ''historical detective'', you are invited to take on the challenges of the mysteries of Okayama Castle, with a message from Ryogo Matsumaru. Take on the challenges written in the scroll!' where id = 'eJZyYZIpVqxxjkapGFesY';
update content_bodies set title = '備中高松城址～空旅時間～ 岡山市を感じるスカイウォーク', description = '岡山市の名所や知られざるスポットを空から旅することができます。かつて毛利氏の要塞であった備中高松城は、羽柴秀吉の参謀・黒田官兵衛の水攻めにより落城しました。城主の清水宗治は自刃し、城は陥落しました。現在は歴史公園として整備され、本丸跡には清水宗治の首塚があり、資料館では水攻めに関する資料が展示されています。夏には花菖蒲や宗治蓮が咲き、来園者を楽しませています。' where id = 'Q36P03J5LJ7vlXFJu57cA';
update content_bodies set title = 'Bichu Takamatsu Castle Ruins - Sky Travel Time - A Skywalk to Experience Okayama City', description = 'Explore Okayama City from above, including famous landmarks and hidden spots. Bichu Takamatsu Castle, once a stronghold of the Mori clan, fell to Toyotomi Hideyoshi''s strategist, Kuroda Kanbei, through a clever water siege. The castle''s lord, Shimizu Munenari, committed seppuku, leading to the castle''s downfall. Today, the site is a historical park featuring the remains of the main keep and a memorial for Shimizu Munenari. The museum displays materials related to the water siege. In summer, visitors can enjoy blooming irises and Munenari lotus flowers.' where id = '1sJF9wQQg4CclL8cSs91n';
update content_bodies set title = '紅葉をみるなら京都へ！おすすめスポット６選', description = 'この動画は、京都を訪れる旅行者に向けて、紅葉を楽しむためのおすすめスポットを6つ紹介しています。動画で紹介されていないおすすめがあれば、コメント欄でシェアしてください。また、旅行の達人公式LINEアカウントでは、旅行に関するお得な情報を配信しています。旅行の達人チャンネルは、観光、宿泊、食事など、旅行に関するさまざまな情報を提供し、旅行を通じて人生を豊かにすることを目指しています。観光地や店舗のPRに関するお問い合わせは、info@ryoko-tatsujin.comまでご連絡ください。' where id = 'H7nTeo9rhWOCwimgGVlzi';
update content_bodies set title = 'Recommended Spots for Autumn Foliage in Kyoto: 6 Must-Visit Locations', description = 'This video serves as a guide for those traveling to Kyoto, showcasing six recommended spots to enjoy the beautiful autumn leaves. If you have any additional recommendations not mentioned in the video, please feel free to share them in the comments. The channel also offers a free LINE account for travel tips and deals, aiming to enhance your travel experience. The channel, operated by travel enthusiasts, provides a wealth of information on various travel aspects, including sightseeing, accommodation, and dining, with the mission of enriching lives through travel. For inquiries related to promoting local attractions or businesses, contact info@ryoko-tatsujin.com.' where id = 'HQquPb9z1LyhRK0TvKOJf';
update content_bodies set title = '【広島観光】広島旅行で訪れたい！アートや魅力いっぱいの生口島', description = 'この動画では、広島県の生口島を紹介しています。生口島は観光に訪れる価値のある場所で、動画に載っていないおすすめがあればコメントでシェアしてください。旅行の達人チャンネルでは、観光、移動、宿泊、食事など、旅行をより楽しくする情報を提供しています。メンバーは旅行を通じて人生を豊かにすることを目指しており、視聴者が新しい可能性を発見できるようサポートしています。最新情報は公式SNSでフォローしてください。' where id = 'QVEBdmrqTR2ljAbAYkfN3';
update content_bodies set title = 'Hiroshima Tourism: Must-Visit Art and Attractions on Ikuchijima Island', description = 'This video introduces Ikuchijima Island, a destination worth visiting during your trip to Hiroshima Prefecture. If you have any recommendations not mentioned in the video, please share them in the comments. The channel, ''Travel Master,'' provides various travel information to enhance your travel experience, including sightseeing, transportation, accommodation, and dining. The team behind the channel aims to enrich lives through travel, encouraging viewers to explore new possibilities and enjoy their journeys. For more information and updates, follow their official social media accounts.' where id = 'nho7-mMCljCTL6Rt_hkZf';
update content_bodies set title = '横須賀の無人島「猿島」で癒しの旅へ', description = '神奈川県への旅行を計画している方に向けて、猿島を紹介する動画です。視聴者には、他のおすすめ情報をコメント欄でシェアするよう促しています。「旅行の達人」チャンネルは、観光、移動、宿泊、食事などの旅行情報を提供し、旅行体験を向上させることを目的としています。運営チームは、旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性や体験を発見することを目指しています。動画では猿島の詳細や自然の魅力、三笠公園や横須賀軍港などの近隣スポットについても触れています。訪問前には公式サイトで最新情報を確認することが推奨されています。' where id = 'k8m49111n2kAdU1B2_jDH';
update content_bodies set title = 'Healing Journey to Sarushima, an Uninhabited Island in Yokosuka', description = 'This video serves as a guide for those planning to travel to Kanagawa Prefecture, specifically highlighting Sarushima. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to provide a wealth of travel information, including sightseeing, transportation, accommodation, and dining, to enhance the travel experience. The team behind the channel believes in enriching lives through travel and aims to inspire viewers to discover new possibilities and experiences. The video includes details about Sarushima, its natural beauty, and nearby attractions such as Mikasa Park and the Yokosuka Naval Port. Viewers are advised to check official websites for the latest information before visiting.' where id = 'NAi9A3R5flaskPtcIs3mK';
update content_bodies set title = '嵐山で食べ歩き！絶品グルメを食べ尽くす！', description = 'この動画は、京都府の嵐山を紹介し、旅行や観光の参考にしてもらうことを目的としています。視聴者には、動画で紹介されていないおすすめのスポットをコメント欄でシェアするよう促しています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事など、旅行に関するさまざまな情報を提供し、旅行をより楽しくすることを目指しています。メンバーは年間の半分近くを旅しており、旅行を通じて人生を豊かにすることを願っています。動画では、嵐山の絶品グルメスポットが紹介されており、地元の美味しい料理やスイーツがリストアップされています。旅行のヒントや最新情報を得るために、公式のSNSアカウントをフォローしたり、チャンネル登録をすることが推奨されています。' where id = 'G9vFvUeLR45MuQctf6usF';
update content_bodies set title = 'Food Walking in Arashiyama, Kyoto! Enjoying Delicious Gourmet!', description = 'This video serves as a guide for those traveling to or sightseeing in Kyoto, specifically highlighting Arashiyama. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a wealth of information on various aspects of travel, including sightseeing, transportation, accommodation, and dining. The mission is to enrich lives through travel, with a team that spends nearly half the year traveling. The video features a list of must-try gourmet spots in Arashiyama, including various local delicacies and treats. For more travel tips and updates, viewers can follow the official social media accounts and subscribe to the channel.' where id = 'KPU_I96Iz5US0XU5HjVMU';
update content_bodies set title = '【奈良観光】絶対おすすめ！奈良の絶景紅葉スポット１５選', description = 'この動画は奈良県への旅行を計画している方に向けて、人気の絶景紅葉スポットを紹介しています。動画で紹介されていないおすすめの場所があれば、ぜひコメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事など、旅行に関するさまざまな情報を提供し、視聴者の旅行体験をより楽しくすることを目指しています。旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見することを促しています。最新の旅行情報を得るために、公式SNSアカウントをフォローしてください。' where id = 'T3U3JeZk1RGCrTt1XHcQS';
update content_bodies set title = 'Recommended! 15 Stunning Autumn Foliage Spots in Nara', description = 'This video serves as a guide for those traveling to Nara Prefecture, showcasing popular spots for breathtaking autumn foliage. If you have any additional recommendations not mentioned in the video, please share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing various travel information, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys. For more travel tips and updates, follow their official social media accounts.' where id = 'BpZ7obEbRR2PIPrSEDTyy';
update content_bodies set title = '紅葉なら筑波山へ！おすすめスポットや見所をご紹介します', description = 'この動画は茨城県への旅行を考えている方に向けて、筑波山の紅葉スポットを紹介しています。視聴者には、他のおすすめがあればコメント欄でシェアするよう呼びかけています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目的としています。メンバーは旅行を通じて人生を豊かにすることを信じており、新しい可能性を発見することを促しています。動画では、紅葉の見頃やアクセス情報、筑波山神社やもみじ祭りなどの見所が紹介されています。訪問前には公式サイトで最新情報を確認するようにとの注意もあります。' where id = 'VUg7s0AAS8z9ws5NpSyQe';
update content_bodies set title = 'Autumn Leaves at Mount Tsukuba: Recommended Spots and Highlights', description = 'This video serves as a guide for those traveling to Ibaraki Prefecture, focusing on the autumn foliage spots at Mount Tsukuba. It invites viewers to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a wealth of information on sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities. The video includes details on the best viewing times for the autumn leaves, access information, and highlights such as the Mount Tsukuba Shrine and the Momiji Festival. Viewers are reminded to check official websites for the latest information before visiting.' where id = 'COm6jjV4BhOyAV40OkOLG';
update content_bodies set title = '【長崎観光】歴史ある世界遺産「端島」の魅力をご紹介', description = 'この動画は長崎県への旅行を考えている方に向けて、端島を紹介する内容です。視聴者には、他のおすすめ情報をコメント欄でシェアするよう促しています。「旅行の達人」チャンネルは、観光、移動、宿泊、食事など、旅行をより楽しくするための情報を提供することを目的としています。運営メンバーは、旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見するきっかけを提供したいと考えています。動画では、端島の詳細、見どころ、上陸ツアー、歴史について説明しており、関連情報へのリンクも掲載されています。訪問前には公式サイトで最新情報を確認することが推奨されています。' where id = '7ObH0C051OzOomm_II9Ty';
update content_bodies set title = 'Exploring the Historical World Heritage Site of Hashima Island in Nagasaki', description = 'This video serves as a guide for those traveling to Nagasaki Prefecture, focusing on Hashima Island. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to provide a wealth of travel information, including sightseeing, transportation, accommodation, and dining, to enhance the travel experience. The team behind the channel believes in enriching lives through travel and aims to inspire viewers to discover new possibilities through their journeys. The video includes details about Hashima Island, its attractions, landing tours, and historical context, along with links to related resources. Viewers are advised to check official sites for the latest information before visiting.' where id = 'zOhz1OR1NML3IqocEdozB';
update content_bodies set title = '【佐賀観光】写真映えなら御船山楽園！おすすめスポットをご紹介します', description = 'この動画は、佐賀県を訪れる旅行者に向けて、四季折々の絶景が楽しめる御船山楽園の魅力を紹介しています。視聴者には、動画で紹介されていないおすすめスポットをコメントでシェアするよう呼びかけています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目的としています。運営メンバーは、旅行を通じて人生を豊かにすることを信じており、視聴者に新しい可能性を発見することを促しています。最新情報は公式SNSでフォローできます。' where id = 'r5tW8xSgyZXQgY4I3n4dS';
update content_bodies set title = 'Savor the Scenic Beauty of Mifuneyama Rakuen in Saga!', description = 'This video serves as a guide for travelers visiting Saga Prefecture, showcasing the breathtaking views available at Mifuneyama Rakuen throughout the seasons. The video invites viewers to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a wealth of information on sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys. For more information and updates, viewers can follow the official social media accounts.' where id = 'DuzzQbLOOTQd0xcC-ltoP';
update content_bodies set title = '【福岡観光】福岡に来たら寄りたい！櫛田神社の見どころをご案内', description = 'この動画は福岡県を訪れる旅行者に向けて、櫛田神社の魅力を紹介しています。視聴者には、コメント欄で他のおすすめ情報を共有するよう促しています。「旅行の達人」チャンネルは、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目指しています。チャンネルの運営メンバーは、旅行を通じて人生を豊かにすることを願っています。動画では、櫛田神社や博多歴史館などの詳細が紹介されており、訪問前には公式サイトで最新情報を確認することが推奨されています。' where id = 'IAVUia_HzehXWuM2Vgj_5';
update content_bodies set title = 'Fukuoka Tourism: Must-Visit Highlights of Kushida Shrine', description = 'This video serves as a guide for those traveling to Fukuoka Prefecture, showcasing the attractions of Kushida Shrine. Viewers are encouraged to share any additional recommendations in the comments section. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a wealth of information on sightseeing, transportation, accommodation, and dining, both domestically and internationally. The mission is to enrich lives through travel, with a team that spends nearly half the year traveling. The video includes details about Kushida Shrine, the Hakata Historical Museum, and other notable sites. For more information, viewers are advised to check official websites before visiting, as details may change.' where id = 'hbHiO_MLyvoZTMoO4Ihmo';
